# C API (`libparakeet.so`)

The README has the overview and the ABI note. This page has the longer examples.
The current ABI version is 10 (`parakeet_capi_abi_version()`); all additions since v5 are additive.
The full symbol list and the exact signatures are in `include/parakeet_capi.h`.

`include/parakeet_capi.h` defines a flat, exception-free C-API meant for `dlopen` / FFI / LocalAI integration. Build the shared library with `-DPARAKEET_SHARED=ON`:

```c
#include "parakeet_capi.h"

parakeet_ctx *ctx = parakeet_capi_load("model.gguf");  // load ONCE
if (!ctx) { fprintf(stderr, "%s\n", parakeet_capi_last_error(ctx)); return 1; }

char *text = parakeet_capi_transcribe_path(ctx, "audio.wav", 0 /*default*/);
if (text) { printf("%s\n", text); parakeet_capi_free_string(text); }

parakeet_capi_free(ctx);
```

In-memory PCM:
```c
char *text = parakeet_capi_transcribe_pcm(ctx, samples, n_samples,
                                          sample_rate, 0 /*default*/);
```

Timestamps and confidence as JSON (matches NeMo `timestamps=True` + `max_prob`):
```c
char *json = parakeet_capi_transcribe_path_json(ctx, "audio.wav", 0 /*default*/);
// {"text":"...",
//  "frame_sec":0.080000,
//  "words":[{"w":"Well,","start":0.480,"end":0.640,"conf":0.7859}, ...],
//  "tokens":[{"id":639,"t":0.480,"conf":0.9969}, ...]}
if (json) { printf("%s\n", json); parakeet_capi_free_string(json); }
```
`start`/`end`/`t` are in seconds; `conf` is the rescaled softmax probability of the emitted token in `(0,1]` (a word's `conf` is the `min` over its tokens). `frame_sec` is the encoder frame stride in seconds (`hop x subsampling / sample_rate`); multiply a frame-unit segment gap threshold (NeMo's `segment_gap_threshold`) by it to get the seconds gap between words when forming segments.

## Streaming (cache-aware EOU model)

For `parakeet_realtime_eou_120m-v1`, a streaming session decodes 16 kHz mono f32 PCM as it arrives, returning newly-finalized text and signalling EOU/EOB events:

```c
parakeet_stream *s = parakeet_capi_stream_begin(ctx);
int eou = 0;
char *t = parakeet_capi_stream_feed(s, pcm, n_samples, &eou); // "" if none yet
if (t) { printf("%s", t); parakeet_capi_free_string(t); }
if (eou) printf(" [EOU]");
// ...feed more chunks...
char *tail = parakeet_capi_stream_finalize(s);                // flush the tail
if (tail) { printf("%s\n", tail); parakeet_capi_free_string(tail); }
parakeet_capi_stream_free(s);
```

`<EOU>` (end-of-utterance) and `<EOB>` (backchannel) are stripped from the text and surfaced via `*eou_out` (the CLI `--stream` prints them as `[EOU @ <t>s]` markers). The streaming transcript matches NeMo's cache-aware streaming exactly, and `finalize` flushes the end-of-stream tail without fabricating an `<EOU>` that NeMo would not emit.

The LocalAI backend (in the LocalAI repo) dlopens `libparakeet.so` and uses these symbols directly: the offline `parakeet_capi_transcribe_*` / `parakeet_capi_transcribe_path_json` and the streaming `parakeet_capi_stream_*`. See `include/parakeet_capi.h` for the full API. The C++ streaming session (`pk::StreamingSession`) also exposes per-word timestamps and confidence as words finalize, via `drain_words()` alongside the EOU events, which the CLI `--stream --timestamps` path prints.

#include "model_loader.hpp"
#include <cstdio>
#include <cstdlib>
#include <string>

int main() {
    const char* env = std::getenv("PARAKEET_TEST_GGUF");
    const char* npath = std::getenv("PARAKEET_TEST_GGUF_NEMOTRON");
    if (!env && !npath) {
        std::fprintf(stderr, "PARAKEET_TEST_GGUF / PARAKEET_TEST_GGUF_NEMOTRON not set; skipping\n");
        return 77;
    }

    // Base model checks (only when PARAKEET_TEST_GGUF points at a fixture).
    if (env) {
        pk::ModelLoader ml;
        if (!ml.load(env)) { std::fprintf(stderr, "load failed\n"); return 1; }
        const pk::ParakeetConfig& c = ml.config();
        if (c.arch.empty())   { std::fprintf(stderr, "empty arch\n"); return 1; }
        if (c.d_model == 0 || c.n_layers == 0 || c.n_heads == 0) { std::fprintf(stderr, "bad encoder dims\n"); return 1; }
        // Diarization models have no vocab (no text output); skip vocab checks.
        if (c.arch != "diarization") {
            if (c.vocab_size == 0) { std::fprintf(stderr, "bad vocab\n"); return 1; }
            if (c.blank_id != c.vocab_size) { std::fprintf(stderr, "blank!=vocab\n"); return 1; }
        }
        // mel filterbank tensor must be present
        if (ml.tensor("preprocessor.featurizer.fb") == nullptr) { std::fprintf(stderr, "no fb\n"); return 1; }
        // first conformer layer norm must be present (verbatim name)
        if (ml.tensor("encoder.layers.0.norm_feed_forward1.weight") == nullptr) {
            std::fprintf(stderr, "no layer0 norm\n"); return 1;
        }
        std::printf("loader ok: arch=%s d_model=%u layers=%u heads=%u vocab=%u\n",
                    c.arch.c_str(), c.d_model, c.n_layers, c.n_heads, c.vocab_size);
    }

    // Prompt-conditioning config (nemotron). Runs whenever the fixture is set,
    // independently of PARAKEET_TEST_GGUF.
    if (npath) {
        pk::ModelLoader nl;
        if (!nl.load(npath)) { std::fprintf(stderr, "load nemotron failed\n"); return 1; }
        const pk::ParakeetConfig& nc = nl.config();
        if (!nc.prompt.present) { std::fprintf(stderr, "prompt.present false\n"); return 1; }
        if (nc.prompt.num_prompts != 128) { std::fprintf(stderr, "num_prompts!=128\n"); return 1; }
        if (nc.prompt.default_lang != "auto") { std::fprintf(stderr, "default_lang!=auto\n"); return 1; }
        if (nc.prompt.lang_to_index("de") != 9) { std::fprintf(stderr, "de!=9\n"); return 1; }
        if (nc.prompt.lang_to_index("auto") != 101) { std::fprintf(stderr, "auto!=101\n"); return 1; }
        if (nc.prompt.lang_to_index("zzz") != -1) { std::fprintf(stderr, "unknown!=-1\n"); return 1; }
        if (nc.use_bias) { std::fprintf(stderr, "use_bias should be false\n"); return 1; }
        std::fprintf(stderr, "nemotron prompt config OK\n");
    }
    return 0;
}

#include "model.hpp"
#include "audio_io.hpp"
#include <cstdlib>
#include <cstdio>
#include <string>
#include <vector>

// Batch-API B=1 equivalence smoke test.
//
// Loads the real-speech fixture, transcribes it single-clip, then runs it as a
// 2-clip batch of the same audio. Asserts both batch results equal the single
// result, proving the batch path gives the same transcript as the single path
// (text equality; batched floats are close, not bit-identical). This is
// self-consistency (our own code on both sides), so it only needs
// PARAKEET_TEST_GGUF.
int main() {
    const char* gguf = std::getenv("PARAKEET_TEST_GGUF");
    if (!gguf) { std::fprintf(stderr, "env not set; skip\n"); return 77; }
    auto model = pk::Model::load(gguf);
    if (!model) { std::fprintf(stderr, "load failed\n"); return 1; }

    pk::Audio audio;
    if (!pk::load_audio_16k_mono("tests/fixtures/speech.wav", audio) || audio.samples.empty()) {
        std::fprintf(stderr, "wav load failed\n");
        return 1;
    }
    const std::vector<float>& pcm = audio.samples;

    std::string single = model->transcribe_pcm(pcm, 16000);
    auto batch = model->transcribe_pcm_batch({pcm, pcm}, 16000);
    if (batch.size() != 2) { std::fprintf(stderr, "batch size %zu\n", batch.size()); return 1; }
    if (batch[0] != single || batch[1] != single) {
        std::fprintf(stderr, "MISMATCH single='%s' b0='%s' b1='%s'\n",
                     single.c_str(), batch[0].c_str(), batch[1].c_str());
        return 1;
    }
    std::fprintf(stderr, "OK batch==single: '%s'\n", single.c_str());
    return 0;
}

// Loader reads parakeet.ternary.* / parakeet.vad.* and leaves other models alone.
// Skips (77) unless the env vars point at converted GGUFs.
#include "model_loader.hpp"

#include <cmath>
#include <cstdio>
#include <cstdlib>

#include "ggml.h"

using namespace pk;

static int failures = 0;
#define CHECK(c) do { if (!(c)) { std::fprintf(stderr, "FAIL: %s (line %d)\n", #c, __LINE__); ++failures; } } while (0)

int main() {
    const char* keep = std::getenv("PARAKEET_TEST_GGUF_REDUX_KEEP");
    const char* plain = std::getenv("PARAKEET_TEST_GGUF");
    if (!keep && !plain) {
        std::puts("skip: PARAKEET_TEST_GGUF_REDUX_KEEP and PARAKEET_TEST_GGUF unset");
        return 77;
    }
    if (keep) {
        ModelLoader ml;
        CHECK(ml.load(keep));
        const ParakeetConfig& c = ml.config();
        CHECK(c.ternary.present);
        CHECK(c.ternary.group_size == 128);
        CHECK(c.vad.present);
        CHECK(c.vad.d_in == 1024 && c.vad.hidden == 128 && c.vad.kernel == 5);
        CHECK(std::fabs(c.vad.frame_sec - 0.08f) < 1e-6f);
        const ggml_tensor* q = ml.tensor("encoder.layers.0.self_attn.linear_q.qweight");
        CHECK(q && q->type == GGML_TYPE_I8 && q->ne[0] == 205 && q->ne[1] == 1024);
        const ggml_tensor* s = ml.tensor("encoder.layers.0.self_attn.linear_q.scales");
        CHECK(s && s->type == GGML_TYPE_F16 && s->ne[0] == 8 && s->ne[1] == 1024);
        CHECK(ml.tensor("encoder.layers.0.self_attn.linear_q.weight") == nullptr);
        const ggml_tensor* p = ml.tensor("encoder.layers.0.feed_forward1.linear2.qweight");
        CHECK(p && p->ne[0] == 820 && p->ne[1] == 1024);  // K = 4096, ceil(4096/5) = 820
        CHECK(ml.tensor("vad_head.proj.weight") != nullptr);
        CHECK(ml.tensor("vad_head.ctx.weight") != nullptr);
        CHECK(ml.tensor("vad_head.out.bias") != nullptr);
    }
    if (plain) {
        ModelLoader ml;
        CHECK(ml.load(plain));
        CHECK(!ml.config().ternary.present);
        CHECK(!ml.config().vad.present);
    }
    if (failures) return 1;
    std::puts("test_model_loader_ternary: OK");
    return 0;
}

#include "parakeet_capi.h"
#include "audio_io.hpp"
#include <cstdlib>
#include <cstdio>
#include <string>
#include <vector>

// The two model env vars are independent: the offline block (PARAKEET_TEST_GGUF)
// exercises the non-lang batch JSON path and its language-aware delegate on a
// real offline model; the prompt block (PARAKEET_TEST_GGUF_NEMOTRON) exercises
// the batched target_lang error handling on a multilingual prompt model. Each
// block runs only when its env var is set; if neither is set we skip (77).
int main() {
    bool ran_any = false;

    // Build a 2-clip batch (speech.wav twice) reused by both blocks.
    pk::Audio a;
    if (!pk::load_audio_16k_mono("tests/fixtures/speech.wav", a) || a.samples.empty()) {
        std::fprintf(stderr, "wav load failed\n"); return 1;
    }
    std::vector<float> concat;
    concat.insert(concat.end(), a.samples.begin(), a.samples.end());
    concat.insert(concat.end(), a.samples.begin(), a.samples.end());
    int n_samples[2] = { (int)a.samples.size(), (int)a.samples.size() };

    const char* gguf = std::getenv("PARAKEET_TEST_GGUF");
    if (gguf) {
        ran_any = true;
        parakeet_ctx* ctx = parakeet_capi_load(gguf);
        if (!ctx) { std::fprintf(stderr, "load failed\n"); return 1; }

        char* single = parakeet_capi_transcribe_path_json(ctx, "tests/fixtures/speech.wav", 0);
        if (!single) { std::fprintf(stderr, "single failed: %s\n", parakeet_capi_last_error(ctx)); parakeet_capi_free(ctx); return 1; }
        std::string single_doc(single);
        parakeet_capi_free_string(single);

        char* batch = parakeet_capi_transcribe_pcm_batch_json(ctx, concat.data(), n_samples, 2, 16000, 0);
        if (!batch) { std::fprintf(stderr, "batch failed: %s\n", parakeet_capi_last_error(ctx)); parakeet_capi_free(ctx); return 1; }
        std::string doc(batch);
        parakeet_capi_free_string(batch);

        auto text_field = [](const std::string& s) -> std::string {
            size_t p = s.find("\"text\":\"");
            if (p == std::string::npos) return "";
            p += 8; size_t q = s.find('"', p);
            return s.substr(p, q - p);
        };
        std::string t = text_field(single_doc);
        bool is_array = !doc.empty() && doc.front() == '[' && doc.back() == ']';
        size_t cnt = 0, pos = 0;
        std::string needle = "\"text\":\"" + t + "\"";
        while ((pos = doc.find(needle, pos)) != std::string::npos) { ++cnt; pos += needle.size(); }
        bool ok = is_array && !t.empty() && cnt == 2;
        std::fprintf(stderr, "array=%d text='%s' count=%zu -> %s\n", is_array, t.c_str(), cnt, ok?"OK":"FAIL");

        // The language-aware delegate with the model default (NULL) must match the
        // non-lang path byte-for-byte on an offline (non-prompt) model.
        char* batch_lang = parakeet_capi_transcribe_pcm_batch_json_lang(ctx, concat.data(), n_samples, 2, 16000, 0, nullptr);
        bool lang_ok = batch_lang && doc == std::string(batch_lang);
        std::fprintf(stderr, "batch_json_lang(NULL)==batch_json -> %s\n", lang_ok?"OK":"FAIL");
        parakeet_capi_free_string(batch_lang);

        parakeet_capi_free(ctx);
        if (!ok || !lang_ok) return 1;
    }

    // Prompt (multilingual / nemotron) model: exercise the batched target_lang
    // variant. This fixture is a CAUSAL streaming prompt model
    // (causal_downsampling=True). Batched causal subsampling is now supported
    // (same transcripts as per-item), so a valid-language 2-clip batch runs through
    // the batched encoder and returns a JSON array of length 2. We also assert
    // the catchable error path: an unknown locale is rejected by
    // resolve_prompt_index (which runs before the encoder) -> NULL + non-empty
    // last_error, proving target_lang is threaded through the batched C-API.
    // Skipped cleanly when the env var is unset.
    const char* nemotron = std::getenv("PARAKEET_TEST_GGUF_NEMOTRON");
    if (nemotron) {
        ran_any = true;
        parakeet_ctx* nctx = parakeet_capi_load(nemotron);
        if (!nctx) { std::fprintf(stderr, "nemotron load failed\n"); return 1; }

        // A valid locale ("de") must return a non-NULL JSON array of length 2.
        char* ngood = parakeet_capi_transcribe_pcm_batch_json_lang(
            nctx, concat.data(), n_samples, 2, 16000, 0, "de");
        if (!ngood) {
            std::fprintf(stderr, "nemotron batch_json_lang(de) returned NULL: %s\n",
                         parakeet_capi_last_error(nctx));
            parakeet_capi_free(nctx);
            return 1;
        }
        std::string ndoc(ngood);
        parakeet_capi_free_string(ngood);
        bool nis_array = !ndoc.empty() && ndoc.front() == '[' && ndoc.back() == ']';
        // Two JSON objects in the array (one per clip).
        size_t nobj = 0, npos = 0;
        while ((npos = ndoc.find("\"text\":", npos)) != std::string::npos) { ++nobj; npos += 7; }
        bool ngood_ok = nis_array && nobj == 2;
        std::fprintf(stderr, "nemotron batch_json_lang(de) array=%d objects=%zu -> %s\n",
                     nis_array, nobj, ngood_ok ? "OK" : "FAIL");
        if (!ngood_ok) { parakeet_capi_free(nctx); return 1; }

        // An unknown locale must fail cleanly: NULL + non-empty last_error.
        char* nbad = parakeet_capi_transcribe_pcm_batch_json_lang(
            nctx, concat.data(), n_samples, 2, 16000, 0, "zzz");
        if (nbad != nullptr) {
            std::fprintf(stderr, "nemotron batch_json_lang(zzz) returned non-NULL\n");
            parakeet_capi_free_string(nbad);
            parakeet_capi_free(nctx);
            return 1;
        }
        const char* nerr = parakeet_capi_last_error(nctx);
        if (!nerr || nerr[0] == '\0') {
            std::fprintf(stderr, "nemotron unknown-lang did not set last_error\n");
            parakeet_capi_free(nctx);
            return 1;
        }
        std::fprintf(stderr, "nemotron unknown-lang error = %s\n", nerr);
        parakeet_capi_free(nctx);
        std::fprintf(stderr, "PASS nemotron batch_json_lang error path\n");
    }

    if (!ran_any) {
        std::fprintf(stderr, "no model env var set (PARAKEET_TEST_GGUF / PARAKEET_TEST_GGUF_NEMOTRON); skip\n");
        return 77;
    }
    return 0;
}

// Redux with packed ternary weights (native kernel) must decode the reference
// clip to the same transcript as the dequantized Redux GGUF.
// Env: PARAKEET_TEST_GGUF_REDUX_KEEP (--ternary keep), PARAKEET_TEST_GGUF_REDUX_DEQ.
#include "model.hpp"
#include "audio_io.hpp"

#include <cstdio>
#include <cstdlib>
#include <string>

using namespace pk;

static const char* kReference =
    "Well, I don't wish to see it any more, observed Phoebe, turning away her eyes. "
    "It is certainly very like the old portrait.";

int main() {
    const char* keep = std::getenv("PARAKEET_TEST_GGUF_REDUX_KEEP");
    const char* deq = std::getenv("PARAKEET_TEST_GGUF_REDUX_DEQ");
    if (!keep || !deq) {
        std::puts("skip: PARAKEET_TEST_GGUF_REDUX_KEEP / _DEQ unset");
        return 77;
    }
    int failures = 0;
    std::string two_deq, two_keep;
    for (const char* path : {deq, keep}) {
        auto m = Model::load(path);
        if (!m) { std::fprintf(stderr, "FAIL: load %s\n", path); return 1; }
        const std::string got = m->transcribe_path("tests/fixtures/speech.wav", Decoder::kTDT);
        std::printf("%s\n  -> %s\n", path, got.c_str());
        if (got != kReference) { std::fprintf(stderr, "FAIL: transcript differs for %s\n", path); ++failures; }
        const std::string two = m->transcribe_path("tests/fixtures/two_speakers.wav", Decoder::kTDT);
        std::printf("  two_speakers -> %s\n", two.c_str());
        (path == keep ? two_keep : two_deq) = two;
        if (path == keep) {
            // batched == per-item on the packed model
            Audio a, b;
            if (!load_audio_16k_mono("tests/fixtures/speech.wav", a) ||
                !load_audio_16k_mono("tests/fixtures/two_speakers.wav", b)) {
                std::fprintf(stderr, "FAIL: fixture load\n");
                return 1;
            }
            const auto batch = m->transcribe_pcm_batch({a.samples, b.samples}, 16000, Decoder::kTDT);
            if (batch.size() != 2 || batch[0] != got || batch[1] != two) {
                std::fprintf(stderr, "FAIL: batched transcripts differ from per-item\n");
                for (const auto& t : batch) std::fprintf(stderr, "  batch: %s\n", t.c_str());
                ++failures;
            }
        }
    }
    if (two_deq != two_keep) {
        std::fprintf(stderr, "FAIL: two_speakers transcript differs between dequantized and packed Redux\n"
                             "  deq : %s\n  keep: %s\n", two_deq.c_str(), two_keep.c_str());
        ++failures;
    }
    if (failures) return 1;
    std::puts("test_ternary_model: OK");
    return 0;
}

// C-API concurrency: set_concurrency return values and the last_error contract
// under concurrent writers. Run it under ThreadSanitizer for the race check.
//
// LABEL model
// WORKING_DIRECTORY (tests run from the project root; wav path is relative)
//
// Env:
//   PARAKEET_TEST_GGUF   ASR model (skip 77 if unset)
#include "parakeet_capi.h"

#include <atomic>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <thread>
#include <vector>

static int failures = 0;
#define CHECK(cond, ...)                                          \
    do {                                                          \
        if (!(cond)) {                                            \
            std::fprintf(stderr, "FAIL %s:%d: ", __FILE__, __LINE__); \
            std::fprintf(stderr, __VA_ARGS__);                    \
            std::fprintf(stderr, "\n");                           \
            ++failures;                                           \
        }                                                         \
    } while (0)

int main() {
    const char* gguf = std::getenv("PARAKEET_TEST_GGUF");
    if (!gguf) return 77;

    // Contract of a NULL context.
    CHECK(parakeet_capi_set_concurrency(nullptr, 2, 1) == 0, "NULL ctx returns 0");

    parakeet_ctx* ctx = parakeet_capi_load(gguf);
    if (!ctx) { std::fprintf(stderr, "load failed\n"); return 1; }

    CHECK(parakeet_capi_set_concurrency(ctx, 0, 0) == 1, "0 clamps to 1");
    CHECK(parakeet_capi_set_concurrency(ctx, 3, 2) == 3, "3 backends");
    CHECK(parakeet_capi_set_concurrency(ctx, 1, 0) == 1, "back to 1 backend");

    // Two failing calls with different messages from many threads at once while
    // one thread reads the error. Every read must be one of the known messages
    // (never torn); under ThreadSanitizer there must be no race report.
    CHECK(parakeet_capi_set_concurrency(ctx, 2, 1) == 2, "2 backends");
    std::atomic<bool> stop{false};
    std::atomic<int> bad_reads{0}, reads{0};
    std::vector<std::thread> writers;
    for (int t = 0; t < 6; ++t)
        writers.emplace_back([&, t] {
            for (int i = 0; i < 400; ++i) {
                char* r = (t % 2)
                    ? parakeet_capi_transcribe_path(ctx, nullptr, 0)
                    : parakeet_capi_transcribe_pcm(ctx, nullptr, 10, 16000, 0);
                if (r) { parakeet_capi_free_string(r); ++bad_reads; }
            }
        });
    std::thread reader([&] {
        while (!stop.load()) {
            const char* e = parakeet_capi_last_error(ctx);
            const std::string s = e ? e : "";
            ++reads;
            if (s != "" && s != "wav_path is NULL" && s != "invalid samples buffer") ++bad_reads;
        }
    });
    for (auto& w : writers) w.join();
    stop = true;
    reader.join();
    CHECK(bad_reads == 0, "unexpected error text or a call that did not fail (%d)", bad_reads.load());
    const std::string last = parakeet_capi_last_error(ctx);
    CHECK(last == "wav_path is NULL" || last == "invalid samples buffer",
          "final error text: '%s'", last.c_str());
    std::printf("last_error reads: %d\n", reads.load());

    parakeet_capi_free(ctx);
    if (failures == 0) std::printf("test_capi_concurrency: ok\n");
    return failures == 0 ? 0 : 1;
}

// Sound stream C-API on real audio: ced.cpp's public-domain demo clips
// (rooster, thunder, guitar) back to back, 6 s each. Needs
// PARAKEET_TEST_CED_GGUF (any CED GGUF). Exit 77 when unset.
#include "parakeet_capi.h"
#include "audio_io.hpp"
#include "ced_tagger.hpp"
#include "sound_stream.hpp"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

// Load a WAV as 16 kHz mono (pk::load_audio_16k_mono downmixes and resamples).
static bool load16k(const std::string& path, std::vector<float>& x) {
    pk::Audio a;
    if (!pk::load_audio_16k_mono(path, a)) return false;
    x = std::move(a.samples);
    return true;
}

static int fails = 0;
#define CHECK(c, ...) do { if (!(c)) { std::fprintf(stderr, "FAIL: " __VA_ARGS__); std::fprintf(stderr, "\n"); ++fails; } } while (0)

int main() {
    const char* gguf = std::getenv("PARAKEET_TEST_CED_GGUF");
    if (!gguf) { std::fprintf(stderr, "SKIP: PARAKEET_TEST_CED_GGUF unset\n"); return 77; }
    if (!pk::CedTagger::available()) { std::fprintf(stderr, "SKIP: built without CED\n"); return 77; }
    parakeet_ctx* tag = parakeet_capi_load(gguf);
    if (!tag) { std::fprintf(stderr, "FAIL: load\n"); return 1; }

    // Build the clip.
    const char* names[] = {"rooster", "thunder", "guitar"};
    std::vector<float> pcm;
    for (const char* n : names) {
        std::vector<float> x;
        const std::string p = std::string(PK_CED_SOURCE_DIR) + "/benchmarks/demo/clips/" + n + ".wav";
        CHECK(load16k(p, x), "read %s", p.c_str());
        pcm.insert(pcm.end(), x.begin(), x.end());
    }

    // opts_validation
    parakeet_sound_opts o;
    parakeet_capi_sound_opts_default(&o);
    CHECK(o.size == (int)sizeof(o) && o.hop_sec == 1.0f && o.window_sec == 3.0f, "defaults");
    parakeet_sound_opts bad = o;
    bad.hop_sec = 5.0f;
    CHECK(parakeet_capi_sound_stream_begin(tag, &bad) == nullptr, "bad opts accepted");
    CHECK(std::strstr(parakeet_capi_last_error(tag), "hop_sec") != nullptr, "bad opts message: %s",
          parakeet_capi_last_error(tag));

    // Stream it in 0.25 s pieces.
    parakeet_sound_stream* s = parakeet_capi_sound_stream_begin(tag, nullptr);
    CHECK(s != nullptr, "begin: %s", parakeet_capi_last_error(tag));
    std::vector<parakeet_sound_segment> segs;
    std::string scores;
    bool checked_active = false;
    for (size_t i = 0; i < pcm.size(); i += 4000) {
        const int n = (int)std::min<size_t>(4000, pcm.size() - i);
        parakeet_sound_segment* out = nullptr;
        int nout = 0;
        CHECK(parakeet_capi_sound_stream_feed(s, pcm.data() + i, n, i + 4000 >= pcm.size(), &out, &nout) == 0,
              "feed: %s", parakeet_capi_last_error(tag));
        for (int k = 0; k < nout; ++k) segs.push_back(out[k]);
        parakeet_capi_free_sound_segments(out);
        char* j = parakeet_capi_sound_stream_drain_scores_json(s);
        CHECK(j != nullptr, "drain");
        if (j) { scores += j; parakeet_capi_free_string(j); }

        // Around 3.5 s in (inside the rooster slot), check the still-open
        // segments: whatever comes back must be internally consistent, even
        // when nothing happens to be open at this exact instant.
        if (!checked_active && i + n >= 3.5 * 16000) {
            checked_active = true;
            parakeet_sound_segment* act = nullptr;
            int nact = 0;
            CHECK(parakeet_capi_sound_stream_active(s, &act, &nact) == 0,
                  "active: %s", parakeet_capi_last_error(tag));
            const double t = (i + n) / 16000.0;
            for (int k = 0; k < nact; ++k) {
                CHECK(act[k].start <= act[k].end, "active start <= end");
                CHECK(std::fabs(act[k].end - t) < 1e-3, "active end == stream time (%.3f vs %.3f)",
                      act[k].end, t);
            }
            parakeet_capi_free_sound_segments(act);
        }
    }
    for (const auto& g : segs)
        std::fprintf(stderr, "  %-24s %6.2f %6.2f %.3f\n", g.label, g.start, g.end, g.peak);

    // Each clip's main label appears, inside its own 6 s slot (one hop slack).
    auto found = [&](const char* label, float lo, float hi) {
        for (const auto& g : segs)
            if (std::strcmp(g.label, label) == 0 && g.start >= lo - 1.0f && g.start < hi) return true;
        return false;
    };
    CHECK(found("Chicken, rooster", 0.0f, 6.0f), "rooster in [0, 6)");
    CHECK(found("Thunder", 6.0f, 12.0f) || found("Thunderstorm", 6.0f, 12.0f), "thunder in [6, 12)");
    CHECK(found("Guitar", 12.0f, 18.0f) || found("Acoustic guitar", 12.0f, 18.0f), "guitar in [12, 18)");
    CHECK(scores.find("\"tags\":[{\"index\":") != std::string::npos, "score json shape");

    // Window scores are exactly CedTagger::scorer()'s numbers for the same
    // samples (test_ced_parity checks those against the PyTorch baseline).
    {
        auto t = pk::CedTagger::load(gguf);
        std::vector<float> direct;
        CHECK(t && t->scorer()(pcm.data(), 16000, direct), "direct score");
        pk::SoundOpts so; so.window_sec = 1.0f; so.hop_sec = 1.0f; so.top_k = 1;
        pk::SoundStream ss(t->scorer(), t->n_classes(), so);
        ss.feed(pcm.data(), 16000, false);
        auto w = ss.drain_windows();
        const float best = *std::max_element(direct.begin(), direct.end());
        CHECK(w.size() == 1 && w[0].top[0].second == best, "window score != direct score");
    }
    // The first window of a 1 s / 1 s stream spans [0, 1).
    {
        parakeet_sound_opts one = o;
        one.window_sec = 1.0f; one.hop_sec = 1.0f; one.top_k = 1;
        parakeet_sound_stream* s1 = parakeet_capi_sound_stream_begin(tag, &one);
        parakeet_sound_segment* out = nullptr; int nout = 0;
        parakeet_capi_sound_stream_feed(s1, pcm.data(), 16000, 0, &out, &nout);
        parakeet_capi_free_sound_segments(out);
        char* j = parakeet_capi_sound_stream_drain_scores_json(s1);
        std::fprintf(stderr, "first window: %s\n", j ? j : "(null)");
        CHECK(j && std::strstr(j, "\"start\":0.000,\"end\":1.000") != nullptr, "first window span");
        parakeet_capi_free_string(j);
        parakeet_capi_sound_stream_free(s1);
    }

    // Finished stream refuses more audio.
    parakeet_sound_segment* out = nullptr; int nout = 0;
    CHECK(parakeet_capi_sound_stream_feed(s, pcm.data(), 10, 0, &out, &nout) != 0, "feed after is_last");
    parakeet_capi_sound_stream_free(s);

    // wrong_ctx_kind: an ASR context is rejected with a clear message.
    if (const char* asr_gguf = std::getenv("PARAKEET_TEST_GGUF")) {
        parakeet_ctx* asr = parakeet_capi_load(asr_gguf);
        CHECK(parakeet_capi_sound_stream_begin(asr, nullptr) == nullptr, "ASR ctx accepted as tagger");
        CHECK(std::strstr(parakeet_capi_last_error(asr), "ASR model") != nullptr, "message: %s",
              parakeet_capi_last_error(asr));
        CHECK(parakeet_capi_num_classes(asr) == -1, "num_classes on ASR ctx");
        CHECK(parakeet_capi_model_kind(asr) == PARAKEET_MODEL_KIND_ASR, "model_kind on ASR ctx");
        parakeet_capi_free(asr);
    }
    CHECK(parakeet_capi_num_classes(tag) == 527, "num_classes");
    CHECK(parakeet_capi_model_kind(tag) == PARAKEET_MODEL_KIND_SOUND, "model_kind on tagger ctx");
    CHECK(parakeet_capi_model_kind(nullptr) == PARAKEET_MODEL_KIND_NONE, "model_kind on NULL");
    parakeet_capi_free(tag);
    if (fails) return 1;
    std::fprintf(stderr, "PASS\n");
    return 0;
}

#include "parakeet_capi.h"
#include "audio_io.hpp"     // pk::load_audio_16k_mono (test links the parakeet lib)
#include "stream_clips.hpp" // pktest::two_utterance_clip

#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

// Streaming JSON C-API smoke test (segment-timestamp support).
//
// Drives parakeet_capi_stream_feed_json / parakeet_capi_stream_finalize_json on
// the cache-aware EOU streaming model and asserts the returned documents carry
// "frame_sec" (> 0) and a "words" array (the per-word start/end timestamps from
// the streaming session's drain_words) — the data LocalAI needs to build
// timestamped per-utterance segments.
//
// Skips (exit 77) unless PARAKEET_TEST_GGUF_EOU is set (the streaming EOU model
// is a ~480MB download, not in CI).
//
// LABEL model
// WORKING_DIRECTORY (run from project root; wav path is relative)

static bool contains(const std::string& hay, const char* needle) {
    return hay.find(needle) != std::string::npos;
}

int main() {
    const char* gguf = std::getenv("PARAKEET_TEST_GGUF_EOU");
    if (!gguf) {
        std::fprintf(stderr,
            "test_capi_stream_json: PARAKEET_TEST_GGUF_EOU not set; skip "
            "(streaming EOU model is a ~480MB download, not in CI)\n");
        return 77;
    }

    pk::Audio audio;
    if (!pk::load_audio_16k_mono("tests/fixtures/speech.wav", audio)) {
        std::fprintf(stderr, "test_capi_stream_json: failed to load speech.wav\n");
        return 1;
    }

    parakeet_ctx* ctx = parakeet_capi_load(gguf);
    if (!ctx) {
        std::fprintf(stderr, "test_capi_stream_json: load failed for %s\n", gguf);
        return 1;
    }
    parakeet_stream* s = parakeet_capi_stream_begin(ctx);
    if (!s) {
        std::fprintf(stderr, "test_capi_stream_json: stream_begin failed: %s\n",
                     parakeet_capi_last_error(ctx));
        parakeet_capi_free(ctx);
        return 1;
    }

    // Feed the PCM in real-time-sized chunks (~100 ms = 1600 samples).
    const int chunk = 1600;
    const int n = (int)audio.samples.size();
    std::string acc;
    for (int off = 0; off < n; off += chunk) {
        const int len = std::min(chunk, n - off);
        char* t = parakeet_capi_stream_feed_json(s, audio.samples.data() + off, len);
        if (!t) {
            std::fprintf(stderr, "test_capi_stream_json: feed_json NULL: %s\n",
                         parakeet_capi_last_error(ctx));
            parakeet_capi_stream_free(s);
            parakeet_capi_free(ctx);
            return 1;
        }
        acc += t;
        parakeet_capi_free_string(t);
    }

    char* fin = parakeet_capi_stream_finalize_json(s);
    if (!fin) {
        std::fprintf(stderr, "test_capi_stream_json: finalize_json NULL: %s\n",
                     parakeet_capi_last_error(ctx));
        parakeet_capi_stream_free(s);
        parakeet_capi_free(ctx);
        return 1;
    }
    acc += fin;
    parakeet_capi_free_string(fin);

    parakeet_capi_stream_free(s);

    std::fprintf(stderr, "test_capi_stream_json: concatenated docs:\n%s\n", acc.c_str());

    if (!contains(acc, "\"frame_sec\"")) {
        std::fprintf(stderr, "test_capi_stream_json: FAIL — no frame_sec in output\n");
        parakeet_capi_free(ctx);
        return 1;
    }
    if (!contains(acc, "\"words\"")) {
        std::fprintf(stderr, "test_capi_stream_json: FAIL — no words array in output\n");
        parakeet_capi_free(ctx);
        return 1;
    }
    // A real transcription must finalize at least one word with a non-zero end.
    if (!contains(acc, "\"end\":")) {
        std::fprintf(stderr, "test_capi_stream_json: FAIL — no word end timestamps\n");
        parakeet_capi_free(ctx);
        return 1;
    }
    // ABI v5: every streaming doc carries the (possibly empty) "events" array
    // and the per-type "eou"/"eob" flags.
    if (!contains(acc, "\"events\"")) {
        std::fprintf(stderr, "test_capi_stream_json: FAIL — no events array in output\n");
        parakeet_capi_free(ctx);
        return 1;
    }
    if (!contains(acc, "\"eou\":") || !contains(acc, "\"eob\":")) {
        std::fprintf(stderr, "test_capi_stream_json: FAIL — missing eou/eob flags\n");
        parakeet_capi_free(ctx);
        return 1;
    }

    // Two-utterance clip (see stream_clips.hpp): an <EOU> fires mid-stream and
    // must appear as a typed entry {"type":"eou","frame":...,"t":...} in some doc.
    {
        std::vector<float> clip = pktest::two_utterance_clip(audio.samples);

        parakeet_stream* s2 = parakeet_capi_stream_begin(ctx);
        if (!s2) {
            std::fprintf(stderr, "test_capi_stream_json: phase-2 stream_begin failed: %s\n",
                         parakeet_capi_last_error(ctx));
            parakeet_capi_free(ctx);
            return 1;
        }
        std::string acc2;
        const int n2 = (int)clip.size();
        for (int off = 0; off < n2; off += chunk) {
            const int len = std::min(chunk, n2 - off);
            char* t = parakeet_capi_stream_feed_json(s2, clip.data() + off, len);
            if (!t) {
                std::fprintf(stderr, "test_capi_stream_json: phase-2 feed_json NULL: %s\n",
                             parakeet_capi_last_error(ctx));
                parakeet_capi_stream_free(s2);
                parakeet_capi_free(ctx);
                return 1;
            }
            acc2 += t;
            parakeet_capi_free_string(t);
        }
        char* fin2 = parakeet_capi_stream_finalize_json(s2);
        if (fin2) { acc2 += fin2; parakeet_capi_free_string(fin2); }
        parakeet_capi_stream_free(s2);

        if (!contains(acc2, "\"type\":\"eou\"")) {
            std::fprintf(stderr,
                "test_capi_stream_json: FAIL — no typed eou event on the "
                "two-utterance clip; docs:\n%s\n", acc2.c_str());
            parakeet_capi_free(ctx);
            return 1;
        }
        // The per-type flag fires with the event (and EOB stays 0 — this clip
        // has no backchannel).
        if (!contains(acc2, "\"eou\":1") || contains(acc2, "\"eob\":1")) {
            std::fprintf(stderr,
                "test_capi_stream_json: FAIL — eou/eob flags wrong on the "
                "two-utterance clip; docs:\n%s\n", acc2.c_str());
            parakeet_capi_free(ctx);
            return 1;
        }
    }

    parakeet_capi_free(ctx);

    std::fprintf(stderr, "test_capi_stream_json: PASS — streaming JSON carries "
                         "frame_sec + per-word timestamps + typed eou/eob events\n");
    return 0;
}

#include "parakeet_capi.h"

#include <cstdio>
#include <cstdlib>
#include <cstring>

// Flat C-API end-to-end test: load -> transcribe -> free.
//
// Loads the 110m anchor GGUF, transcribes tests/fixtures/speech.wav with the
// TDT head (decoder == 2), and asserts the returned transcript equals the known
// NeMo TDT reference. Also checks that loading a nonexistent path returns NULL
// (no crash, exception contained at the boundary).
//
// LABEL model
// WORKING_DIRECTORY (tests run from the project root; wav path is relative)
//
// Env:
//   PARAKEET_TEST_GGUF            model weights (skip 77 if unset)
//   PARAKEET_TEST_GGUF_NEMOTRON   prompt (multilingual) model; if set, also
//                                 exercises the target_lang C-API variants

static const char* kExpected =
    "Well, I don't wish to see it any more, observed Phoebe, turning away her "
    "eyes. It is certainly very like the old portrait.";

int main() {
    // ABI version must be a sane positive integer.
    if (parakeet_capi_abi_version() < 1) {
        std::fprintf(stderr, "test_capi: abi version < 1\n");
        return 1;
    }

    // Loading a nonexistent model must fail gracefully (NULL, no crash).
    parakeet_ctx* bad = parakeet_capi_load("/nonexistent/x.gguf");
    if (bad != nullptr) {
        std::fprintf(stderr, "test_capi: load of nonexistent path returned non-NULL\n");
        parakeet_capi_free(bad);
        return 1;
    }

    // A NULL context reports PARAKEET_MODEL_KIND_NONE.
    if (parakeet_capi_model_kind(nullptr) != PARAKEET_MODEL_KIND_NONE) {
        std::fprintf(stderr, "test_capi: model_kind(NULL) != NONE\n");
        return 1;
    }

    // The 110m anchor (PARAKEET_TEST_GGUF) and the prompt/multilingual model
    // (PARAKEET_TEST_GGUF_NEMOTRON) are independent: each block runs only when
    // its env var is set. If NEITHER is set the test skips (77).
    bool ran_any = false;

    const char* gguf = std::getenv("PARAKEET_TEST_GGUF");
    if (gguf) {
        ran_any = true;
        parakeet_ctx* ctx = parakeet_capi_load(gguf);
        if (!ctx) {
            std::fprintf(stderr, "test_capi: parakeet_capi_load failed for %s\n", gguf);
            return 1;
        }

        if (parakeet_capi_model_kind(ctx) != PARAKEET_MODEL_KIND_ASR) {
            std::fprintf(stderr, "test_capi: model_kind(ASR ctx) != ASR\n");
            parakeet_capi_free(ctx);
            return 1;
        }

        // decoder == 2 -> TDT/transducer head.
        char* text = parakeet_capi_transcribe_path(ctx, "tests/fixtures/speech.wav", 2);
        if (!text) {
            std::fprintf(stderr, "test_capi: transcribe_path returned NULL: %s\n",
                         parakeet_capi_last_error(ctx));
            parakeet_capi_free(ctx);
            return 1;
        }

        std::fprintf(stderr, "test_capi: got      = %s\n", text);
        std::fprintf(stderr, "test_capi: expected = %s\n", kExpected);

        const bool match = std::strcmp(text, kExpected) == 0;
        parakeet_capi_free_string(text);
        parakeet_capi_free(ctx);

        if (!match) {
            std::fprintf(stderr, "test_capi: MISMATCH vs NeMo TDT reference\n");
            return 1;
        }
        std::fprintf(stderr, "test_capi: PASS (word-for-word match with NeMo TDT)\n");
    } else {
        std::fprintf(stderr, "test_capi: PARAKEET_TEST_GGUF not set; skip anchor block\n");
    }

    // Prompt (multilingual) model: exercise the target_lang variants. Skipped
    // cleanly when PARAKEET_TEST_GGUF_NEMOTRON is unset.
    const char* nemotron = std::getenv("PARAKEET_TEST_GGUF_NEMOTRON");
    if (nemotron) {
        ran_any = true;
        parakeet_ctx* nctx = parakeet_capi_load(nemotron);
        if (!nctx) {
            std::fprintf(stderr, "test_capi: load failed for nemotron %s\n", nemotron);
            return 1;
        }

        // A known language prompt must transcribe (non-NULL).
        char* de = parakeet_capi_transcribe_path_lang(
            nctx, "tests/fixtures/speech.wav", 0, "de");
        if (!de) {
            std::fprintf(stderr, "test_capi: transcribe_path_lang(de) returned NULL: %s\n",
                         parakeet_capi_last_error(nctx));
            parakeet_capi_free(nctx);
            return 1;
        }
        std::fprintf(stderr, "test_capi: nemotron de = %s\n", de);
        parakeet_capi_free_string(de);

        // An unknown locale must fail cleanly: NULL + non-empty last_error.
        char* bad_lang = parakeet_capi_transcribe_path_lang(
            nctx, "tests/fixtures/speech.wav", 0, "zzz");
        if (bad_lang != nullptr) {
            std::fprintf(stderr, "test_capi: transcribe_path_lang(zzz) returned non-NULL\n");
            parakeet_capi_free_string(bad_lang);
            parakeet_capi_free(nctx);
            return 1;
        }
        const char* err = parakeet_capi_last_error(nctx);
        if (!err || err[0] == '\0') {
            std::fprintf(stderr, "test_capi: unknown-lang did not set last_error\n");
            parakeet_capi_free(nctx);
            return 1;
        }
        std::fprintf(stderr, "test_capi: nemotron unknown-lang error = %s\n", err);

        // Streaming path must reject an unknown locale exactly like the offline
        // path: NULL + non-empty last_error (no silent fallback to the default).
        parakeet_stream* bad_stream = parakeet_capi_stream_begin_lang(nctx, "zzz");
        if (bad_stream != nullptr) {
            std::fprintf(stderr,
                "test_capi: stream_begin_lang(zzz) returned non-NULL\n");
            parakeet_capi_stream_free(bad_stream);
            parakeet_capi_free(nctx);
            return 1;
        }
        const char* serr = parakeet_capi_last_error(nctx);
        if (!serr || serr[0] == '\0') {
            std::fprintf(stderr,
                "test_capi: stream unknown-lang did not set last_error\n");
            parakeet_capi_free(nctx);
            return 1;
        }
        std::fprintf(stderr, "test_capi: nemotron stream unknown-lang error = %s\n",
                     serr);

        // A known language prompt must begin a stream (non-NULL); free it.
        parakeet_stream* ok_stream = parakeet_capi_stream_begin_lang(nctx, "en");
        if (!ok_stream) {
            std::fprintf(stderr,
                "test_capi: stream_begin_lang(en) returned NULL: %s\n",
                parakeet_capi_last_error(nctx));
            parakeet_capi_free(nctx);
            return 1;
        }
        parakeet_capi_stream_free(ok_stream);

        parakeet_capi_free(nctx);
        std::fprintf(stderr, "test_capi: PASS nemotron target_lang variants\n");
    } else {
        std::fprintf(stderr,
            "test_capi: PARAKEET_TEST_GGUF_NEMOTRON not set; skip prompt block\n");
    }

    if (!ran_any) {
        std::fprintf(stderr,
            "test_capi: no model env var set (PARAKEET_TEST_GGUF / "
            "PARAKEET_TEST_GGUF_NEMOTRON); skip\n");
        return 77;
    }
    return 0;
}

// Registry entry points that need no model: add_embedding, size, save, load,
// errors. Model independent.
#include "parakeet_capi.h"

#include <cmath>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <limits>
#include <string>

static int failures = 0;
#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            std::fprintf(stderr, "FAIL: %s (line %d)\n", #cond, __LINE__);  \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

int main() {
    CHECK(parakeet_capi_abi_version() == 10);

    parakeet_speaker_registry* reg = parakeet_capi_speaker_registry_new();
    CHECK(reg != nullptr);
    const float a[4] = {1, 0, 0, 0};
    const float b[4] = {0, 1, 0, 0};
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ada", a, 4) == 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ben", b, 4) == 0);
    CHECK(parakeet_capi_speaker_registry_size(reg) == 2);
    // Same name again: averaged into the same speaker, not a third one.
    const float a2[4] = {0.9f, 0.1f, 0, 0};
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ada", a2, 4) == 0);
    CHECK(parakeet_capi_speaker_registry_size(reg) == 2);

    // Errors, each leaves the registry unchanged and says why on the registry.
    const float c3[3] = {1, 0, 0};
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "cy", c3, 3) != 0);
    CHECK(std::strstr(parakeet_capi_speaker_registry_last_error(reg), "expects") != nullptr);
    const float nan4[4] = {std::numeric_limits<float>::quiet_NaN(), 0, 0, 0};
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "dee", nan4, 4) != 0);
    const float inf4[4] = {std::numeric_limits<float>::infinity(), 0, 0, 0};
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "dee", inf4, 4) != 0);
    const float zero4[4] = {0, 0, 0, 0};
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "dee", zero4, 4) != 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "", a, 4) != 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, nullptr, a, 4) != 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ee", nullptr, 4) != 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ee", a, 0) != 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ee", a, -1) != 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(nullptr, "ee", a, 4) != 0);
    CHECK(parakeet_capi_speaker_registry_size(reg) == 2);
    // A success clears the message.
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "ben", b, 4) == 0);
    CHECK(std::strlen(parakeet_capi_speaker_registry_last_error(reg)) == 0);

    // A registry filled this way saves and loads like any other.
    const std::filesystem::path p = std::filesystem::temp_directory_path() / "pk_test_add_embedding.bin";
    std::filesystem::remove(p);
    CHECK(parakeet_capi_speaker_registry_save(reg, p.string().c_str()) == 0);
    parakeet_speaker_registry* back = parakeet_capi_speaker_registry_load(p.string().c_str());
    CHECK(back != nullptr && parakeet_capi_speaker_registry_size(back) == 2);
    // And a loaded registry keeps its dimension: a wrong-sized vector is refused.
    if (back) CHECK(parakeet_capi_speaker_registry_add_embedding(back, "cy", c3, 3) != 0);
    parakeet_capi_speaker_registry_free(back);
    std::filesystem::remove(p);

    parakeet_capi_speaker_registry_free(reg);

    // Encoder fingerprint (additive, ABI stays 10).
    {
        const char* fam = "voicedetect:ecapa_tdnn:ecapa:4";
        const char* w1 = "sha256:1111";
        parakeet_speaker_registry* f = parakeet_capi_speaker_registry_new();
        CHECK(std::strlen(parakeet_capi_speaker_registry_encoder_family(f)) == 0);
        CHECK(std::strlen(parakeet_capi_speaker_registry_encoder_weights(f)) == 0);
        CHECK(parakeet_capi_speaker_registry_add_embedding_fp(f, "ada", a, 4, fam, w1) == 0);
        CHECK(std::strcmp(parakeet_capi_speaker_registry_encoder_family(f), fam) == 0);
        CHECK(std::strcmp(parakeet_capi_speaker_registry_encoder_weights(f), w1) == 0);
        // Same family again, other weights: accepted.
        CHECK(parakeet_capi_speaker_registry_add_embedding_fp(f, "ben", b, 4, fam, "sha256:2222") == 0);
        CHECK(std::strcmp(parakeet_capi_speaker_registry_encoder_weights(f), w1) == 0);
        // Other family, and no fingerprint at all, are refused with a message.
        CHECK(parakeet_capi_speaker_registry_add_embedding_fp(f, "cy", a, 4, "voicedetect:campplus:c:4", w1) != 0);
        CHECK(std::strstr(parakeet_capi_speaker_registry_last_error(f), "campplus") != nullptr);
        CHECK(parakeet_capi_speaker_registry_add_embedding(f, "cy", a, 4) != 0);
        CHECK(parakeet_capi_speaker_registry_size(f) == 2);
        // NULL fingerprint arguments on the _fp call mean "none".
        parakeet_speaker_registry* n = parakeet_capi_speaker_registry_new();
        CHECK(parakeet_capi_speaker_registry_add_embedding_fp(n, "ada", a, 4, nullptr, nullptr) == 0);
        CHECK(std::strlen(parakeet_capi_speaker_registry_encoder_family(n)) == 0);
        // A fingerprint into a non-empty unfingerprinted registry is refused, not stamped.
        CHECK(parakeet_capi_speaker_registry_add_embedding_fp(n, "ben", b, 4, fam, w1) != 0);
        CHECK(parakeet_capi_speaker_registry_encoder_family(nullptr) != nullptr);
        // The fingerprint survives save and load.
        const std::filesystem::path q = std::filesystem::temp_directory_path() / "pk_test_fp_registry.bin";
        CHECK(parakeet_capi_speaker_registry_save(f, q.string().c_str()) == 0);
        parakeet_speaker_registry* back2 = parakeet_capi_speaker_registry_load(q.string().c_str());
        CHECK(back2 && std::strcmp(parakeet_capi_speaker_registry_encoder_family(back2), fam) == 0);
        CHECK(back2 && std::strcmp(parakeet_capi_speaker_registry_encoder_weights(back2), w1) == 0);
        // An unfingerprinted registry is still a v1 file.
        CHECK(parakeet_capi_speaker_registry_save(n, q.string().c_str()) == 0);
        { std::FILE* fh = std::fopen(q.string().c_str(), "rb"); unsigned char h[8] = {0};
          CHECK(fh && std::fread(h, 1, 8, fh) == 8 && h[4] == 1);
          if (fh) std::fclose(fh); }
        std::filesystem::remove(q);
        parakeet_capi_speaker_registry_set_strict(n, 1);   // no crash on NULL either
        parakeet_capi_speaker_registry_set_strict(nullptr, 1);
        CHECK(parakeet_capi_speaker_encoder_family(nullptr) == nullptr);
        CHECK(parakeet_capi_speaker_last_warning(nullptr) != nullptr);
        parakeet_capi_speaker_registry_free(back2);
        parakeet_capi_speaker_registry_free(n);
        parakeet_capi_speaker_registry_free(f);
    }
    if (failures) { std::fprintf(stderr, "%d failure(s)\n", failures); return 1; }
    std::printf("test_capi_speaker_registry: PASS\n");
    return 0;
}

