#include <vector>

// Flat C-API JSON timestamps test (Task 4 of the timestamps+confidence plan).
//
// Loads the parakeet-tdt_ctc-110m anchor GGUF, calls
// parakeet_capi_transcribe_path_json on tests/fixtures/speech.wav with the TDT
// head (decoder == 2), and asserts against the Task 3 validated result:
//   * the "text" field equals the known NeMo TDT transcript,
//   * the words array has exactly 23 entries,
//   * the first word is "Well," with start ~= 0.48 s and a sensible word conf
//     (the 'min' aggregate over its tokens, ~0.79 per the validated baseline),
//   * the JSON also carries a non-empty "tokens" array.
// Parsing is intentionally minimal (a tiny hand-rolled object scanner over the
// JSON the C-API emits) — enough to validate the contract without a JSON lib.
//
// LABEL model
// WORKING_DIRECTORY (tests run from the project root; the wav path is relative)
//
// Env:
//   PARAKEET_TEST_GGUF   model weights (skip 77 if unset)

static const char* kExpected =
    "Well, I don't wish to see it any more, observed Phoebe, turning away her "
    "eyes. It is certainly very like the old portrait.";

namespace {

// One parsed word object {"w","start","end","conf"}.
struct JWord {
    std::string w;
    double start = 0.0, end = 0.0, conf = 0.0;
};

// Tiny scanner over the C-API JSON. Not a general JSON parser — it understands
// exactly the document parakeet_capi_transcribe_path_json emits.
struct Scan {
    const std::string& s;
    size_t i = 0;
    explicit Scan(const std::string& str) : s(str) {}
    void ws() { while (i < s.size() && (s[i]==' '||s[i]=='\t'||s[i]=='\n'||s[i]=='\r')) ++i; }
    bool eat(char c) { ws(); if (i < s.size() && s[i]==c) { ++i; return true; } return false; }
    bool str(std::string& out) {
        ws();
        if (i >= s.size() || s[i] != '"') return false;
        ++i; out.clear();
        while (i < s.size() && s[i] != '"') {
            if (s[i] == '\\' && i + 1 < s.size()) {
                char c = s[i+1];
                switch (c) {
                    case 'n': out += '\n'; break; case 't': out += '\t'; break;
                    case 'r': out += '\r'; break; case 'b': out += '\b'; break;
                    case 'f': out += '\f'; break; case '"': out += '"'; break;
                    case '\\': out += '\\'; break; case '/': out += '/'; break;
                    default: out += c; break;
                }
                i += 2;
            } else { out += s[i++]; }
        }
        if (i >= s.size()) return false;
        ++i; return true;
    }
    bool num(double& out) {
        ws();
        size_t st = i;
        while (i < s.size() && std::strchr("+-0123456789.eE", s[i])) ++i;
        if (i == st) return false;
        out = std::strtod(s.substr(st, i - st).c_str(), nullptr);
        return true;
    }
    // Find the next key matching `key` at the current position, returning after
    // its ':'; advances to the value. (Linear scan from current i.)
    bool seek_key(const char* key) {
        std::string pat = std::string("\"") + key + "\"";
        size_t p = s.find(pat, i);
        if (p == std::string::npos) return false;
        i = p + pat.size();
        return eat(':');
    }
};

// Parse the "words":[ ... ] array out of the JSON into `out`.
bool parse_words(const std::string& s, std::vector<JWord>& out) {
    Scan sc(s);
    if (!sc.seek_key("words")) return false;
    if (!sc.eat('[')) return false;
    sc.ws();
    if (sc.i < s.size() && s[sc.i] == ']') return true;  // empty
    while (true) {
        if (!sc.eat('{')) return false;
        JWord jw;
        bool gw=false, gs=false, ge=false, gc=false;
        while (true) {
            std::string key;
            if (!sc.str(key)) return false;
            if (!sc.eat(':')) return false;
            if (key == "w")          { if (!sc.str(jw.w))    return false; gw = true; }
            else if (key == "start") { if (!sc.num(jw.start)) return false; gs = true; }
            else if (key == "end")   { if (!sc.num(jw.end))   return false; ge = true; }
            else if (key == "conf")  { if (!sc.num(jw.conf))  return false; gc = true; }
            else { return false; }
            if (sc.eat(',')) continue;
            break;
        }
        if (!sc.eat('}')) return false;
        if (!(gw && gs && ge && gc)) return false;
        out.push_back(std::move(jw));
        if (sc.eat(',')) continue;
        break;
    }
    return sc.eat(']');
}

bool parse_text(const std::string& s, std::string& out) {
    Scan sc(s);
    if (!sc.seek_key("text")) return false;
    return sc.str(out);
}

} // namespace

int main() {
    // ABI version sanity.
    if (parakeet_capi_abi_version() < 1) {
        std::fprintf(stderr, "test_capi_timestamps: abi version < 1\n");
        return 1;
    }

    const char* gguf = std::getenv("PARAKEET_TEST_GGUF");
    if (!gguf) {
        std::fprintf(stderr, "test_capi_timestamps: PARAKEET_TEST_GGUF not set; skip\n");
        return 77;
    }

    parakeet_ctx* ctx = parakeet_capi_load(gguf);
    if (!ctx) {
        std::fprintf(stderr, "test_capi_timestamps: load failed for %s\n", gguf);
        return 1;
    }

    // decoder == 2 -> TDT/transducer head.
    char* json = parakeet_capi_transcribe_path_json(ctx, "tests/fixtures/speech.wav", 2);
    if (!json) {
        std::fprintf(stderr, "test_capi_timestamps: transcribe_path_json NULL: %s\n",
                     parakeet_capi_last_error(ctx));
        parakeet_capi_free(ctx);
        return 1;
    }

    const std::string doc(json);
    parakeet_capi_free_string(json);
    parakeet_capi_free(ctx);

    std::fprintf(stderr, "test_capi_timestamps: json head = %.120s ...\n", doc.c_str());

    bool ok = true;

    // text field == known transcript.
    std::string text;
    if (!parse_text(doc, text)) {
        std::fprintf(stderr, "test_capi_timestamps: no \"text\" field\n");
        ok = false;
    } else if (text != kExpected) {
        std::fprintf(stderr, "test_capi_timestamps: text MISMATCH\n  got = %s\n  exp = %s\n",
                     text.c_str(), kExpected);
        ok = false;
    }

    // tokens array present and non-empty (substring check is enough).
    if (doc.find("\"tokens\":[{\"id\":") == std::string::npos) {
        std::fprintf(stderr, "test_capi_timestamps: missing/empty \"tokens\" array\n");
        ok = false;
    }

    // words array: 23 entries, first is "Well," with start ~= 0.48 and conf ~= 0.79.
    std::vector<JWord> words;
    if (!parse_words(doc, words)) {
        std::fprintf(stderr, "test_capi_timestamps: failed to parse \"words\"\n");
        ok = false;
    } else {
        if (words.size() != 23) {
            std::fprintf(stderr, "test_capi_timestamps: word COUNT got=%zu exp=23\n",
                         words.size());
            ok = false;
        }
        if (!words.empty()) {
            const JWord& w0 = words[0];
            std::fprintf(stderr,
                "test_capi_timestamps: word[0] = '%s' start=%.3f end=%.3f conf=%.4f\n",
                w0.w.c_str(), w0.start, w0.end, w0.conf);
            if (w0.w != "Well,") {
                std::fprintf(stderr, "test_capi_timestamps: word[0] text != 'Well,'\n");
                ok = false;
            }
            // start ~= 0.48 s (within one 0.08 s frame).
            if (std::fabs(w0.start - 0.48) > 0.085) {
                std::fprintf(stderr, "test_capi_timestamps: word[0].start %.3f != ~0.48\n",
                             w0.start);
                ok = false;
            }
            // conf is the 'min' aggregate over the word's tokens (~0.79 per the
            // Task 3 NeMo-validated baseline); allow a generous band.
            if (w0.conf < 0.70 || w0.conf > 0.85) {
                std::fprintf(stderr, "test_capi_timestamps: word[0].conf %.4f not ~0.79\n",
                             w0.conf);
                ok = false;
            }
            if (!(w0.end > w0.start)) {
                std::fprintf(stderr, "test_capi_timestamps: word[0].end <= start\n");
                ok = false;
            }
        }
    }

    if (!ok) { std::fprintf(stderr, "test_capi_timestamps: FAIL\n"); return 1; }
    std::fprintf(stderr, "test_capi_timestamps: PASS\n");
    return 0;
}

// A real bundle against its single-model files: the transcript, the VAD head
// probabilities and the Silero probabilities are identical, through the C++ API
// and through the C-API, and loading one component does not read the others.
//
// LABEL model; run from the project root (fixtures are relative).
// Env (skip 77 without the first three):
//   PARAKEET_TEST_BUNDLE         the bundle GGUF (an "asr" and a "vad" component)
//   PARAKEET_TEST_BUNDLE_ASR     the single-model ASR GGUF the "asr" component was built from
//   PARAKEET_TEST_BUNDLE_SILERO  the Silero GGUF the "vad" component was built from
//   PARAKEET_TEST_BUNDLE_EXPECT  optional: the exact transcript of tests/fixtures/speech.wav
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include <sys/stat.h>

#include "audio_io.hpp"
#include "bundle.hpp"
#include "model.hpp"
#include "parakeet_capi.h"
#include "silero_vad.hpp"
#include "vad_json.hpp"

static int failures = 0;
#define CHECK(c) do { if (!(c)) { std::fprintf(stderr, "FAIL: %s (line %d)\n", #c, __LINE__); ++failures; } } while (0)

static unsigned long long bytes_read() {
    std::FILE* f = std::fopen("/proc/self/io", "r");
    if (!f) return 0;
    char k[64];
    unsigned long long v = 0, r = 0;
    while (std::fscanf(f, "%63s %llu", k, &v) == 2)
        if (std::string(k) == "rchar:") r = v;
    std::fclose(f);
    return r;
}

static std::string take(char* p) {
    std::string s = p ? p : "";
    if (p) parakeet_capi_free_string(p);
    return s;
}

static bool same_bits(const std::vector<float>& a, const std::vector<float>& b) {
    return a.size() == b.size() && std::memcmp(a.data(), b.data(), a.size() * sizeof(float)) == 0;
}

int main() {
    const char* bundle = std::getenv("PARAKEET_TEST_BUNDLE");
    const char* asr_path = std::getenv("PARAKEET_TEST_BUNDLE_ASR");
    const char* sil_path = std::getenv("PARAKEET_TEST_BUNDLE_SILERO");
    if (!bundle || !asr_path || !sil_path) {
        std::puts("skip: PARAKEET_TEST_BUNDLE, _ASR and _SILERO must be set");
        return 77;
    }
    const char* expect = std::getenv("PARAKEET_TEST_BUNDLE_EXPECT");
    const std::string wav = "tests/fixtures/speech.wav";
    pk::Audio audio;
    CHECK(pk::load_audio_16k_mono(wav, audio));

    pk::BundleInfo info;
    std::string err;
    CHECK(pk::read_bundle_info(bundle, info, &err));
    const pk::BundleComponent* ac = info.find("asr");
    const pk::BundleComponent* vc = info.find("vad");
    CHECK(ac && vc);
    if (!ac || !vc) return 1;
    CHECK(!ac->license.empty() && !vc->license.empty() && ac->license != vc->license);
    CHECK(vc->license == "MIT");
    struct stat st{};
    CHECK(::stat(bundle, &st) == 0);

    // ---- ASR: transcript identical to the single-model file ----
    auto solo = pk::Model::load(asr_path);
    CHECK(solo != nullptr);
    CHECK(!pk::Model::load(bundle));   // a bundle without a component is refused
    const unsigned long long r0 = bytes_read();
    auto bun = pk::Model::load(bundle, "asr");
    const unsigned long long r1 = bytes_read();
    CHECK(bun != nullptr);
    if (!solo || !bun) return 1;
    const std::string t0 = solo->transcribe_path(wav), t1 = bun->transcribe_path(wav);
    std::printf("standalone: %s\nbundle    : %s\n", t0.c_str(), t1.c_str());
    CHECK(!t0.empty() && t0 == t1);
    if (expect) CHECK(t1 == expect);
    // Only the asr component's tensors are read (plus the header).
    if (r1 > r0) {
        std::printf("bytes read for asr: %.1f MB (component %.1f MB, file %.1f MB)\n", (double)(r1 - r0) / 1e6,
                    (double)ac->n_bytes / 1e6, (double)st.st_size / 1e6);
        CHECK(r1 - r0 < ac->n_bytes + (8u << 20));
        CHECK(r1 - r0 < (unsigned long long)st.st_size - vc->n_bytes / 2);
    }

    // ---- VAD head (Ultra/Redux) from the bundle's ASR component ----
    if (solo->config().vad.present) {
        CHECK(bun->config().vad.present && bun->config().vad.frame_sec == solo->config().vad.frame_sec);
        const std::vector<float> p0 = solo->vad_probabilities(audio.samples), p1 = bun->vad_probabilities(audio.samples);
        CHECK(!p0.empty() && same_bits(p0, p1));
        pk::VadRequest req;
        req.opts = pk::default_segmenter_opts(pk::VadKind::kHead);
        req.probabilities = true;
        CHECK(pk::vad_to_json(*solo, audio.samples, req) == pk::vad_to_json(*bun, audio.samples, req));
    } else {
        std::puts("note: the ASR component has no VAD head");
    }

    // ---- Silero from the bundle ----
    std::string e0, e1;
    auto s0 = pk::SileroVad::load(sil_path, &e0);
    const unsigned long long q0 = bytes_read();
    auto s1 = pk::SileroVad::load(bundle, &e1, "vad");
    const unsigned long long q1 = bytes_read();
    CHECK(s0 && s1);
    if (s0 && s1) {
        const std::vector<float> a = s0->probabilities(audio.samples.data(), audio.samples.size(), 16000);
        const std::vector<float> b = s1->probabilities(audio.samples.data(), audio.samples.size(), 16000);
        CHECK(!a.empty() && same_bits(a, b));
        pk::VadRequest req;
        req.kind = pk::VadKind::kSilero;
        req.opts = pk::default_segmenter_opts(pk::VadKind::kSilero);
        req.probabilities = true;
        CHECK(pk::silero_vad_to_json(*s0, audio.samples, 16000, req) == pk::silero_vad_to_json(*s1, audio.samples, 16000, req));
        // ASR transcription cut by the bundle's Silero equals the one cut by the single file's Silero.
        pk::SegmenterOpts opts = pk::default_segmenter_opts(pk::VadKind::kSilero);
        auto fn = [](const pk::SileroVad* sv) {
            return pk::Model::VadProbabilityFn([sv](const std::vector<float>& pcm) {
                return sv->probabilities(pcm.data(), pcm.size(), 16000);
            });
        };
        pk::Model::VadProbabilityFn f0 = fn(s0.get()), f1 = fn(s1.get());
        const std::string v0 = solo->transcribe_pcm_vad(audio.samples, audio.sample_rate, pk::Decoder::kDefault, "", opts, &f0);
        const std::string v1 = bun->transcribe_pcm_vad(audio.samples, audio.sample_rate, pk::Decoder::kDefault, "", opts, &f1);
        CHECK(!v0.empty() && v0 == v1);
        if (q1 > q0) {
            std::printf("bytes read for vad: %.2f MB (component %.2f MB)\n", (double)(q1 - q0) / 1e6, (double)vc->n_bytes / 1e6);
            CHECK(q1 - q0 < vc->n_bytes + (4u << 20));   // far below the ASR component
        }
    }

    // ---- C-API ----
    {
        parakeet_ctx* a0 = parakeet_capi_load(asr_path);
        parakeet_ctx* a1 = parakeet_capi_load(bundle);               // auto-selects the ASR component
        parakeet_ctx* a2 = parakeet_capi_load_component(bundle, "asr");
        parakeet_ctx* v0 = parakeet_capi_load(sil_path);
        parakeet_ctx* v1 = parakeet_capi_load_component(bundle, "vad");
        CHECK(a0 && a1 && a2 && v0 && v1);
        if (a0 && a1 && a2 && v0 && v1) {
            CHECK(parakeet_capi_model_kind(a1) == PARAKEET_MODEL_KIND_ASR);
            CHECK(parakeet_capi_model_kind(v1) == PARAKEET_MODEL_KIND_VAD);
            const std::string c0 = take(parakeet_capi_transcribe_path(a0, wav.c_str(), 0));
            const std::string c1 = take(parakeet_capi_transcribe_path(a1, wav.c_str(), 0));
            const std::string c2 = take(parakeet_capi_transcribe_path(a2, wav.c_str(), 0));
            CHECK(!c0.empty() && c0 == c1 && c0 == c2 && c0 == t0);
            const char* opt = "{\"probabilities\":true}";
            CHECK(take(parakeet_capi_vad_path_json(v0, wav.c_str(), opt)) == take(parakeet_capi_vad_path_json(v1, wav.c_str(), opt)));
            if (solo->config().vad.present)
                CHECK(take(parakeet_capi_vad_path_json(a0, wav.c_str(), opt)) == take(parakeet_capi_vad_path_json(a1, wav.c_str(), opt)));
            // segmented transcription cut by the bundle's Silero
            const std::string j0 = take(parakeet_capi_transcribe_path_json_vad_with(a0, v0, wav.c_str(), 0, nullptr));
            const std::string j1 = take(parakeet_capi_transcribe_path_json_vad_with(a1, v1, wav.c_str(), 0, nullptr));
            CHECK(!j0.empty() && j0 == j1);
        }
        parakeet_capi_free(a0); parakeet_capi_free(a1); parakeet_capi_free(a2);
        parakeet_capi_free(v0); parakeet_capi_free(v1);
        const std::string js = take(parakeet_capi_bundle_components_json(bundle));
        CHECK(js.find("\"name\":\"asr\"") != std::string::npos && js.find("\"name\":\"vad\"") != std::string::npos);
    }

    if (failures) return 1;
    std::printf("test_bundle_models OK\n");
    return 0;
}

// Speaker identification through the flat C-API.
//   PARAKEET_TEST_DIAR_GGUF, PARAKEET_TEST_VD_GGUF (both required, else skip 77)
//   PARAKEET_TEST_GGUF       optional ASR GGUF; adds the named speaker-attributed ASR check
#include "parakeet_capi.h"

#include "audio_io.hpp"

#include <algorithm>
#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <filesystem>
#include <string>
#include <vector>

static int failures = 0;
#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            std::fprintf(stderr, "FAIL: %s (line %d)\n", #cond, __LINE__);  \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

static std::vector<float> slice(const std::vector<float>& x, double a, double b) {
    return std::vector<float>(x.begin() + (long)(a * 16000), x.begin() + (long)(b * 16000));
}

int main() {
    const char* diar_path = std::getenv("PARAKEET_TEST_DIAR_GGUF");
    const char* vd_path = std::getenv("PARAKEET_TEST_VD_GGUF");
    if (!diar_path || !vd_path) return 77;

    CHECK(parakeet_capi_abi_version() == 10);

    parakeet_ctx* spk = parakeet_capi_load(vd_path);
    if (!spk) { std::fprintf(stderr, "FAIL: load speaker model (built without voice-detect?)\n"); return 77; }
    CHECK(parakeet_capi_model_kind(spk) == PARAKEET_MODEL_KIND_SPEAKER);
    CHECK(parakeet_capi_speaker_dim(spk) >= 128);
    parakeet_ctx* diar = parakeet_capi_load(diar_path);
    CHECK(diar && parakeet_capi_speaker_dim(diar) == -1);
    CHECK(parakeet_capi_model_kind(diar) == PARAKEET_MODEL_KIND_DIARIZATION);

    pk::Audio wav;
    if (!pk::load_audio_16k_mono(std::string(PK_SOURCE_DIR) + "/tests/fixtures/two_speakers.wav", wav)) return 1;
    const auto a0 = slice(wav.samples, 0.6, 4.6), b0 = slice(wav.samples, 6.9, 10.9);

    parakeet_speaker_registry* reg = parakeet_capi_speaker_registry_new();
    CHECK(parakeet_capi_speaker_enroll(reg, spk, "speaker_a", a0.data(), (int)a0.size(), 16000) == 0);
    CHECK(parakeet_capi_speaker_enroll(reg, spk, "speaker_b", b0.data(), (int)b0.size(), 16000) == 0);
    CHECK(parakeet_capi_speaker_registry_size(reg) == 2);
    // Errors: empty name, no audio, wrong ctx kind.
    CHECK(parakeet_capi_speaker_enroll(reg, spk, "", a0.data(), (int)a0.size(), 16000) != 0);
    CHECK(parakeet_capi_speaker_enroll(reg, spk, "x", nullptr, 0, 16000) != 0);
    CHECK(parakeet_capi_speaker_enroll(reg, diar, "x", a0.data(), (int)a0.size(), 16000) != 0);
    CHECK(parakeet_capi_speaker_registry_size(reg) == 2);

    // One-shot identify of clips not used for enrollment.
    {
        const auto a1 = slice(wav.samples, 14.9, 18.7);
        char* j = parakeet_capi_speaker_identify_pcm_json(reg, spk, a1.data(), (int)a1.size(), 16000);
        CHECK(j && std::strstr(j, "\"name\":\"speaker_a\"") != nullptr);
        parakeet_capi_free_string(j);
        const auto b1 = slice(wav.samples, 20.2, 23.5);
        j = parakeet_capi_speaker_identify_pcm_json(reg, spk, b1.data(), (int)b1.size(), 16000);
        CHECK(j && std::strstr(j, "\"name\":\"speaker_b\"") != nullptr);
        parakeet_capi_free_string(j);
    }

    // Save and load round trip, and a corrupt file is refused without crashing.
    const std::filesystem::path tmp_dir = std::filesystem::temp_directory_path();
    const std::string path = (tmp_dir / "pk_test_capi_speaker_registry.bin").string();
    std::filesystem::remove(path);
    CHECK(parakeet_capi_speaker_registry_save(reg, path.c_str()) == 0);
    parakeet_speaker_registry* back = parakeet_capi_speaker_registry_load(path.c_str());
    CHECK(back && parakeet_capi_speaker_registry_size(back) == 2);
    parakeet_capi_speaker_registry_free(back);
    // Saving over an existing registry replaces it, and leaves no tmp file.
    {
        parakeet_speaker_registry* one = parakeet_capi_speaker_registry_new();
        CHECK(parakeet_capi_speaker_enroll(one, spk, "only_a", a0.data(), (int)a0.size(), 16000) == 0);
        CHECK(parakeet_capi_speaker_registry_save(one, path.c_str()) == 0);
        CHECK(!std::filesystem::exists(path + ".tmp"));
        parakeet_speaker_registry* again = parakeet_capi_speaker_registry_load(path.c_str());
        CHECK(again && parakeet_capi_speaker_registry_size(again) == 1);
        parakeet_capi_speaker_registry_free(again);
        // A failed save (directory that does not exist) reports an error and
        // leaves the file that was there loadable.
        const std::string bad = (tmp_dir / "pk_test_no_such_dir" / "registry.bin").string();
        CHECK(parakeet_capi_speaker_registry_save(reg, bad.c_str()) != 0);
        CHECK(std::strlen(parakeet_capi_speaker_registry_last_error(reg)) > 0);
        parakeet_speaker_registry* still = parakeet_capi_speaker_registry_load(path.c_str());
        CHECK(still && parakeet_capi_speaker_registry_size(still) == 1);
        parakeet_capi_speaker_registry_free(still);
        parakeet_capi_speaker_registry_free(one);
    }
    { FILE* f = std::fopen(path.c_str(), "wb"); std::fputs("garbage", f); std::fclose(f); }
    CHECK(parakeet_capi_speaker_registry_load(path.c_str()) == nullptr);
    CHECK(parakeet_capi_speaker_registry_load((tmp_dir / "pk_test_no_such_dir" / "registry.bin").string().c_str()) == nullptr);
    std::filesystem::remove(path);

    // Scene stream with diarization + speaker.
    {
        parakeet_scene_opts o;
        parakeet_capi_scene_opts_default(&o);
        parakeet_scene_stream* s = parakeet_capi_scene_stream_begin_speaker(nullptr, diar, nullptr, spk, reg, &o);
        CHECK(s != nullptr);
        std::string last;
        const int chunk = 3200, n = (int)wav.samples.size();
        for (int lo = 0; lo < n && s; lo += chunk) {
            const int len = std::min(chunk, n - lo);
            char* j = parakeet_capi_scene_stream_feed_json(s, wav.samples.data() + lo, len, lo + len >= n);
            CHECK(j != nullptr);
            if (j) { last = j; parakeet_capi_free_string(j); }
        }
        CHECK(last.find("\"names\":{") != std::string::npos);
        CHECK(last.find("\"name\":\"speaker_a\"") != std::string::npos);
        CHECK(last.find("\"name\":\"speaker_b\"") != std::string::npos);
        parakeet_capi_scene_stream_free(s);
    }
    // A speaker ctx without diarization, or a registry missing, is refused with an error on the ctx.
    {
        parakeet_scene_opts o;
        parakeet_capi_scene_opts_default(&o);
        CHECK(parakeet_capi_scene_stream_begin_speaker(nullptr, nullptr, nullptr, spk, reg, &o) == nullptr);
        CHECK(std::strlen(parakeet_capi_last_error(spk)) > 0);
        CHECK(parakeet_capi_scene_stream_begin_speaker(nullptr, diar, nullptr, spk, nullptr, &o) == nullptr);
        // Old entry point still works exactly as before.
        parakeet_scene_stream* s = parakeet_capi_scene_stream_begin(nullptr, diar, nullptr, &o);
        CHECK(s != nullptr);
        parakeet_capi_scene_stream_free(s);
    }
    // An old-sized opts struct (no speaker fields) is accepted and uses defaults.
    {
        parakeet_scene_opts o;
        parakeet_capi_scene_opts_default(&o);
        o.size = (int)offsetof(parakeet_scene_opts, speaker_accept_threshold);
        parakeet_scene_stream* s = parakeet_capi_scene_stream_begin_speaker(nullptr, diar, nullptr, spk, reg, &o);
        CHECK(s != nullptr);
        parakeet_capi_scene_stream_free(s);
    }
    // Invalid speaker fields are ignored when `size` does not cover them, and
    // rejected when it does.
    {
        parakeet_scene_opts o;
        parakeet_capi_scene_opts_default(&o);
        o.speaker_refresh_sec = -1.0f;
        o.speaker_min_voice_sec = -1.0f;
        o.speaker_accept_threshold = 5.0f;
        o.size = (int)offsetof(parakeet_scene_opts, speaker_accept_threshold);
        parakeet_scene_stream* s = parakeet_capi_scene_stream_begin_speaker(nullptr, diar, nullptr, spk, reg, &o);
        CHECK(s != nullptr);
        parakeet_capi_scene_stream_free(s);
        o.size = (int)sizeof(o);
        CHECK(parakeet_capi_scene_stream_begin_speaker(nullptr, diar, nullptr, spk, reg, &o) == nullptr);
        CHECK(std::strstr(parakeet_capi_last_error(spk), "invalid speaker options") != nullptr);
    }
    // Memory safety: a caller built against the v8 header owns a buffer that ends
    // at `flags`. Nothing past it may be read (run under AddressSanitizer).
    {
        struct OldOpts {
            int size;
            int diar_latency;
            parakeet_sound_opts sound;
            int flags;
        };
        parakeet_scene_opts full;
        parakeet_capi_scene_opts_default(&full);
        OldOpts* old = (OldOpts*)std::malloc(sizeof(OldOpts));
        CHECK(old != nullptr);
        if (old) {
            old->size = (int)sizeof(OldOpts);
            old->diar_latency = full.diar_latency;
            old->sound = full.sound;
            old->flags = 0;
            parakeet_scene_stream* s = parakeet_capi_scene_stream_begin_speaker(
                nullptr, diar, nullptr, spk, reg, (const parakeet_scene_opts*)old);
            CHECK(s != nullptr);
            parakeet_capi_scene_stream_free(s);
            std::free(old);
        }
    }
    // A registry built by a model with a different embedding size is refused with a
    // clear error. Needs a second speaker GGUF of another size (for example WeSpeaker
    // 256 versus CAM++ 192): PARAKEET_TEST_VD_GGUF_ALT. Skipped when unset.
    if (const char* alt_path = std::getenv("PARAKEET_TEST_VD_GGUF_ALT")) {
        parakeet_ctx* alt = parakeet_capi_load(alt_path);
        CHECK(alt != nullptr);
        if (alt && parakeet_capi_speaker_dim(alt) != parakeet_capi_speaker_dim(spk)) {
            parakeet_speaker_registry* wrong = parakeet_capi_speaker_registry_new();
            CHECK(parakeet_capi_speaker_enroll(wrong, alt, "x", a0.data(), (int)a0.size(), 16000) == 0);
            // identify with the main model against the alt-sized registry
            CHECK(parakeet_capi_speaker_identify_pcm_json(wrong, spk, a0.data(), (int)a0.size(), 16000) == nullptr);
            CHECK(std::strstr(parakeet_capi_last_error(spk), "-value embeddings") != nullptr);
            // and a scene stream refuses it up front
            parakeet_scene_opts o;
            parakeet_capi_scene_opts_default(&o);
            CHECK(parakeet_capi_scene_stream_begin_speaker(nullptr, diar, nullptr, spk, wrong, &o) == nullptr);
            CHECK(std::strstr(parakeet_capi_last_error(spk), "embeddings") != nullptr);
            parakeet_capi_speaker_registry_free(wrong);
        }
        parakeet_capi_free(alt);
    }

    // Named speaker-attributed ASR (optional: needs an ASR model).
    if (const char* asr_path = std::getenv("PARAKEET_TEST_GGUF")) {
        parakeet_ctx* asr = parakeet_capi_load(asr_path);
        CHECK(asr != nullptr);
        char* j = parakeet_capi_transcribe_and_diarize_named_json(asr, diar, spk, reg, wav.samples.data(),
                                                                   (int)wav.samples.size(), 16000);
        CHECK(j != nullptr);
        if (j) {
            CHECK(std::strstr(j, "\"name\":\"speaker_a\"") != nullptr);
            CHECK(std::strstr(j, "\"name\":\"speaker_b\"") != nullptr);
            CHECK(std::strstr(j, "\"names\":{") != nullptr);
            parakeet_capi_free_string(j);
        }
        parakeet_capi_free(asr);
    }

    parakeet_capi_speaker_registry_free(reg);
    parakeet_capi_free(diar);
    parakeet_capi_free(spk);
    if (failures) { std::fprintf(stderr, "%d failure(s)\n", failures); return 1; }
    std::printf("test_capi_speaker: PASS\n");
    return 0;
}

