// Streaming C-API end-to-end parity test (Phase 5c, Task 7).
//
// Drives the flat streaming C-API on the cache-aware EOU streaming model
// nvidia/parakeet_realtime_eou_120m-v1:
//   parakeet_capi_stream_begin
//     -> feed tests/fixtures/speech.wav PCM in real-time-sized chunks via
//        parakeet_capi_stream_feed (concatenating the newly-finalized text)
//     -> parakeet_capi_stream_finalize (flush the tail)
//   -> assert the concatenated transcript EQUALS baseline.stream_text from
//      /tmp/baseline_eou_stream.gguf — NeMo's OWN cache-aware streaming decode
//      transcript (<EOU>/<EOB> stripped, handled identically).
//
// The streaming reference (gen_stream_baseline.py) drives NeMo's
// conformer_stream_step carrying previous_hypotheses (partial_hypotheses) across
// chunks — the exact decoder-state-carry this C-API mirrors. For this clip NeMo
// streaming emits 44 tokens == offline rnnt_token_ids minus the trailing
// streaming-tail <EOU> (the final chunk's right context is incomplete by design,
// so neither NeMo nor we emit it during the stream — and finalize does NOT
// fabricate it). stream.eou_in_stream==0 records that no <EOU> fired in-stream.
//
// Skips (exit 77) unless PARAKEET_TEST_GGUF_EOU + PARAKEET_TEST_BASELINE_EOU_STREAM
// are set (the streaming EOU model is a ~480MB download, not in CI).
//
// LABEL model
// WORKING_DIRECTORY (run from project root; wav path is relative)

int main() {
    const char* gguf = std::getenv("PARAKEET_TEST_GGUF_EOU");
    const char* base = std::getenv("PARAKEET_TEST_BASELINE_EOU_STREAM");
    if (!gguf || !base) {
        std::fprintf(stderr,
            "test_capi_stream: PARAKEET_TEST_GGUF_EOU and/or "
            "PARAKEET_TEST_BASELINE_EOU_STREAM not set; skip (streaming EOU model "
            "is a ~480MB download, not in CI)\n");
        return 77;
    }

    // --- NeMo streaming reference: transcript + token ids ---
    std::string ref_text;
    if (!pktest::load_kv_str(base, "baseline.stream_text", ref_text)) {
        std::fprintf(stderr, "test_capi_stream: baseline.stream_text not in %s\n", base);
        return 1;
    }
    std::vector<int32_t> ref_ids;
    if (!pktest::load_baseline_i32(base, "stream_token_ids", ref_ids)) {
        std::fprintf(stderr, "test_capi_stream: stream_token_ids not in %s\n", base);
        return 1;
    }
    std::fprintf(stderr, "test_capi_stream: ref stream_text = %s\n", ref_text.c_str());
    std::fprintf(stderr, "test_capi_stream: ref stream tokens = %zu\n", ref_ids.size());

    // --- Load the clip PCM (16 kHz mono) ---
    pk::Audio audio;
    if (!pk::load_audio_16k_mono("tests/fixtures/speech.wav", audio)) {
        std::fprintf(stderr, "test_capi_stream: failed to load speech.wav\n");
        return 1;
    }

    // --- Load model + begin a stream ---
    parakeet_ctx* ctx = parakeet_capi_load(gguf);
    if (!ctx) {
        std::fprintf(stderr, "test_capi_stream: parakeet_capi_load failed for %s\n", gguf);
        return 1;
    }
    parakeet_stream* s = parakeet_capi_stream_begin(ctx);
    if (!s) {
        std::fprintf(stderr, "test_capi_stream: stream_begin failed: %s\n",
                     parakeet_capi_last_error(ctx));
        parakeet_capi_free(ctx);
        return 1;
    }

    // --- Feed the PCM in real-time-sized chunks (~100 ms = 1600 samples) ---
    const int chunk = 1600;
    const int n = (int)audio.samples.size();
    std::string acc;
    bool any_eou = false;
    for (int off = 0; off < n; off += chunk) {
        const int len = std::min(chunk, n - off);
        int eou = 0;
        char* t = parakeet_capi_stream_feed(s, audio.samples.data() + off, len, &eou);
        if (!t) {
            std::fprintf(stderr, "test_capi_stream: stream_feed returned NULL: %s\n",
                         parakeet_capi_last_error(ctx));
            parakeet_capi_stream_free(s);
            parakeet_capi_free(ctx);
            return 1;
        }
        if (eou) any_eou = true;
        acc += t;
        parakeet_capi_free_string(t);
    }

    // --- Finalize: flush the streaming tail ---
    char* fin = parakeet_capi_stream_finalize(s);
    if (!fin) {
        std::fprintf(stderr, "test_capi_stream: stream_finalize returned NULL: %s\n",
                     parakeet_capi_last_error(ctx));
        parakeet_capi_stream_free(s);
        parakeet_capi_free(ctx);
        return 1;
    }
    acc += fin;
    parakeet_capi_free_string(fin);

    parakeet_capi_stream_free(s);

    std::fprintf(stderr, "test_capi_stream: got stream_text = %s\n", acc.c_str());
    std::fprintf(stderr, "test_capi_stream: any in-stream EOU event = %s\n",
                 any_eou ? "yes" : "no");

    const bool text_ok = (acc == ref_text);
    if (!text_ok) {
        std::fprintf(stderr,
            "test_capi_stream: TEXT MISMATCH vs NeMo streaming reference\n"
            "  got:      %s\n"
            "  expected: %s\n",
            acc.c_str(), ref_text.c_str());
        parakeet_capi_free(ctx);
        return 1;
    }

    // --- Phase 2: drain_events on a TWO-utterance clip (ABI v5) ---
    // An <EOU> fires mid-stream (see stream_clips.hpp). The typed drain must
    // surface it with is_eob==0 and a sane absolute timestamp; the per-feed
    // event mask and the drained queue must agree.
    {
        std::vector<float> clip = pktest::two_utterance_clip(audio.samples);

        parakeet_stream* s2 = parakeet_capi_stream_begin(ctx);
        if (!s2) {
            std::fprintf(stderr, "test_capi_stream: phase-2 stream_begin failed: %s\n",
                         parakeet_capi_last_error(ctx));
            parakeet_capi_free(ctx);
            return 1;
        }
        int flagged_feeds = 0;
        std::vector<parakeet_stream_event> drained;
        const int n2 = (int)clip.size();
        for (int off = 0; off < n2; off += chunk) {
            const int len = std::min(chunk, n2 - off);
            int eou = 0;
            char* t = parakeet_capi_stream_feed(s2, clip.data() + off, len, &eou);
            if (!t) {
                std::fprintf(stderr, "test_capi_stream: phase-2 feed NULL: %s\n",
                             parakeet_capi_last_error(ctx));
                parakeet_capi_stream_free(s2);
                parakeet_capi_free(ctx);
                return 1;
            }
            parakeet_capi_free_string(t);
            parakeet_stream_event* evs = nullptr;
            const int n_ev = parakeet_capi_stream_drain_events(s2, &evs);
            if (n_ev < 0) {
                std::fprintf(stderr, "test_capi_stream: drain_events errored: %s\n",
                             parakeet_capi_last_error(ctx));
                parakeet_capi_stream_free(s2);
                parakeet_capi_free(ctx);
                return 1;
            }
            // The bare feed's event mask and the typed queue must agree per feed.
            int want_mask = 0;
            for (int i = 0; i < n_ev; ++i)
                want_mask |= evs[i].is_eob ? PARAKEET_EVENT_EOB : PARAKEET_EVENT_EOU;
            if (eou != want_mask) {
                std::fprintf(stderr,
                    "test_capi_stream: FAIL — feed event mask (%d) disagrees with "
                    "drained events (want %d from %d events)\n", eou, want_mask, n_ev);
                parakeet_capi_free_events(evs);
                parakeet_capi_stream_free(s2);
                parakeet_capi_free(ctx);
                return 1;
            }
            if (eou) ++flagged_feeds;
            drained.insert(drained.end(), evs, evs + n_ev);
            parakeet_capi_free_events(evs);
        }
        char* fin2 = parakeet_capi_stream_finalize(s2);
        if (fin2) parakeet_capi_free_string(fin2);
        {
            // Events from the finalize flush (e.g. a trailing end-of-clip <EOU>)
            // land in the same queue.
            parakeet_stream_event* evs = nullptr;
            const int n_ev = parakeet_capi_stream_drain_events(s2, &evs);
            if (n_ev > 0) drained.insert(drained.end(), evs, evs + n_ev);
            parakeet_capi_free_events(evs);
        }
        parakeet_capi_stream_free(s2);

        const float clip_secs = (float)n2 / 16000.0f;
        if (drained.empty() || flagged_feeds < 1) {
            std::fprintf(stderr,
                "test_capi_stream: FAIL — no <EOU> event drained on the "
                "two-utterance clip (flagged feeds=%d)\n", flagged_feeds);
            parakeet_capi_free(ctx);
            return 1;
        }
        float prev_t = -1.0f;
        for (const parakeet_stream_event& e : drained) {
            const bool sane = (e.is_eob == 0 || e.is_eob == 1) &&
                              e.encoder_frame >= 0 &&
                              e.time_sec >= prev_t &&
                              e.time_sec <= clip_secs + 1.0f;
            if (!sane) {
                std::fprintf(stderr,
                    "test_capi_stream: FAIL — bad event record (token=%d is_eob=%d "
                    "frame=%d t=%.3f, clip=%.2fs)\n",
                    e.token, e.is_eob, e.encoder_frame, e.time_sec, clip_secs);
                parakeet_capi_free(ctx);
                return 1;
            }
            prev_t = e.time_sec;
            std::fprintf(stderr, "test_capi_stream: event %s frame=%d t=%.3fs\n",
                         e.is_eob ? "<EOB>" : "<EOU>", e.encoder_frame, e.time_sec);
        }
    }

    parakeet_capi_free(ctx);

    std::fprintf(stderr,
        "test_capi_stream: PASS — streaming C-API transcript == NeMo cache-aware "
        "streaming decode (%zu ref tokens, EOU stripped + surfaced as events; "
        "no in-stream <EOU> for this clip, matching NeMo eou_in_stream=0), and "
        "drain_events surfaces typed <EOU>/<EOB> records on the two-utterance "
        "clip\n",
        ref_ids.size());
    return 0;
}

// Standalone VAD through the C-API: speech regions on a synthetic
// speech/silence pattern, options, probabilities, resampling, the error paths,
// and several threads on one context and on separate contexts.
//
// LABEL model; run from the project root (fixtures are relative).
// Env:
//   PARAKEET_TEST_GGUF_ULTRA  a model with a VAD head (skip 77 if unset)
//   PARAKEET_TEST_GGUF_REDUX_KEEP  optional second model with a VAD head
//   PARAKEET_TEST_GGUF        a model without a VAD head (optional)
#include "parakeet_capi.h"
#include "audio_io.hpp"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <random>
#include <string>
#include <thread>
#include <utility>
#include <vector>

static int failures = 0;
#define CHECK(c) do { if (!(c)) { std::fprintf(stderr, "FAIL: %s (line %d)\n", #c, __LINE__); ++failures; } } while (0)

struct Seg { double s, e; };

// Reads the numbers after `"start":` / `"end":` pairs in the "segments" array.
static std::vector<Seg> segments_of(const std::string& j) {
    std::vector<Seg> out;
    size_t pos = j.find("\"segments\":[");
    if (pos == std::string::npos) return out;
    const size_t end = j.find(']', pos);
    while (true) {
        pos = j.find("\"start\":", pos);
        if (pos == std::string::npos || pos > end) break;
        Seg g{};
        g.s = std::atof(j.c_str() + pos + 8);
        const size_t q = j.find("\"end\":", pos);
        g.e = std::atof(j.c_str() + q + 6);
        out.push_back(g);
        pos = q + 6;
    }
    return out;
}

static std::vector<double> probs_of(const std::string& j) {
    std::vector<double> out;
    size_t pos = j.find("\"probabilities\":[");
    if (pos == std::string::npos) return out;
    pos += 17;
    while (j[pos] != ']') {
        char* e = nullptr;
        out.push_back(std::strtod(j.c_str() + pos, &e));
        pos = (size_t)(e - j.c_str());
        if (j[pos] == ',') ++pos;
    }
    return out;
}

static std::string take(char* p) {
    if (!p) return std::string();
    std::string s(p);
    parakeet_capi_free_string(p);
    return s;
}

// Total length of [a, b] covered by regions.
static double covered(const std::vector<Seg>& r, double a, double b) {
    double t = 0;
    for (const auto& g : r) t += std::max(0.0, std::min(g.e, b) - std::max(g.s, a));
    return t;
}

int main() {
    const char* ultra = std::getenv("PARAKEET_TEST_GGUF_ULTRA");
    if (!ultra) { std::puts("skip: PARAKEET_TEST_GGUF_ULTRA unset"); return 77; }
    const char* redux = std::getenv("PARAKEET_TEST_GGUF_REDUX_KEEP");
    const char* plain = std::getenv("PARAKEET_TEST_GGUF");

    // Synthetic clip: 2.0 s silence, speech, 2.5 s silence, speech, 2.0 s silence.
    pk::Audio sp;
    if (!pk::load_audio_16k_mono("tests/fixtures/speech.wav", sp)) { std::fprintf(stderr, "no fixture\n"); return 1; }
    const double sp_len = (double)sp.samples.size() / 16000.0;
    std::mt19937 rng(1);
    std::normal_distribution<float> nd(0.f, 0.0005f);
    auto silence = [&](double sec) { std::vector<float> v((size_t)(sec * 16000)); for (auto& x : v) x = nd(rng); return v; };
    std::vector<float> clip;
    auto add = [&](const std::vector<float>& v) { clip.insert(clip.end(), v.begin(), v.end()); };
    add(silence(2.0)); add(sp.samples); add(silence(2.5)); add(sp.samples); add(silence(2.0));
    const double a0 = 2.0, a1 = 2.0 + sp_len, b0 = a1 + 2.5, b1 = b0 + sp_len;
    const double total = (double)clip.size() / 16000.0;

    parakeet_ctx* ctx = parakeet_capi_load(ultra);
    if (!ctx) { std::fprintf(stderr, "load failed\n"); return 1; }

    // 1. Defaults: speech regions on the original timeline.
    const std::string j = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, nullptr));
    std::printf("%s\n", j.c_str());
    CHECK(!j.empty());
    CHECK(j.find("\"mode\":\"speech\"") != std::string::npos);
    CHECK(j.find("\"frame_sec\":0.080") != std::string::npos);
    CHECK(j.find("\"backend\":\"") != std::string::npos);
    CHECK(j.find("\"probabilities\"") == std::string::npos);
    const std::vector<Seg> r = segments_of(j);
    CHECK(!r.empty());
    for (size_t i = 0; i < r.size(); ++i) {
        CHECK(r[i].e > r[i].s);
        CHECK(r[i].s >= 0 && r[i].e <= total + 0.01);
        if (i) CHECK(r[i].s >= r[i - 1].e);
    }
    const double tol = 0.4;  // the head is a 80 ms frame model; edges are soft
    CHECK(!r.empty() && std::fabs(r.front().s - a0) < tol);
    CHECK(!r.empty() && std::fabs(r.back().e - b1) < tol);
    // Mostly speech inside the speech spans, nothing inside the gaps.
    CHECK(covered(r, a0, a1) > 0.8 * sp_len);
    CHECK(covered(r, b0, b1) > 0.8 * sp_len);
    CHECK(covered(r, 0.0, a0 - tol) < 1e-9);
    CHECK(covered(r, a1 + tol, b0 - tol) < 1e-9);
    CHECK(covered(r, b1 + tol, total) < 1e-9);

    // 2. Options: probabilities and a stricter threshold.
    const std::string jp = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000,
                                                          "{\"probabilities\": true, \"threshold\": 0.5}"));
    const std::vector<double> p = probs_of(jp);
    CHECK(std::llabs((long long)p.size() - (long long)std::ceil(total / 0.08)) <= 2);
    CHECK(segments_of(jp).size() == r.size());
    {
        double lo = 0, hi = 0;
        for (size_t i = 0; i < p.size(); ++i) { const double t = (double)i * 0.08; if (t > 0.2 && t < a0 - 0.3) lo += p[i]; if (t > a0 + 0.5 && t < a1 - 0.5) hi += p[i]; }
        CHECK(hi / std::max(1.0, (a1 - a0 - 1.0) / 0.08) > 0.5);
        CHECK(lo / std::max(1.0, (a0 - 0.5) / 0.08) < 0.3);
    }
    const std::string jhigh = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"threshold\":0.999}"));
    CHECK(covered(segments_of(jhigh), 0, total) <= covered(r, 0, total) + 1e-9);
    // A huge min_pause merges everything between the first and last speech.
    const std::string jm = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"min_pause\":4}"));
    CHECK(segments_of(jm).size() == 1);

    // 3. "segments" mode: the transcriber's cuts. A clip over the cap is cut at pauses.
    {
        std::vector<float> longclip;
        for (int i = 0; i < 4; ++i) {
            longclip.insert(longclip.end(), clip.begin(), clip.end());
        }
        const double lt = (double)longclip.size() / 16000.0;
        const std::string js = take(parakeet_capi_vad_pcm_json(ctx, longclip.data(), (int)longclip.size(), 16000,
                                                              "{\"mode\":\"segments\",\"max_segment\":15}"));
        CHECK(js.find("\"mode\":\"segments\"") != std::string::npos);
        const auto sg = segments_of(js);
        CHECK(sg.size() >= 4);
        for (const auto& g : sg) CHECK(g.e - g.s <= 15.0 + 1e-6);
        CHECK(covered(sg, 0, lt) > 0.8 * 8 * sp_len);
        // Audio within the cap is returned whole, as the transcriber does.
        const std::string jw = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"mode\":\"segments\"}"));
        const auto w = segments_of(jw);
        CHECK(w.size() == 1 && w[0].s == 0.0 && std::fabs(w[0].e - total) < 0.002);
    }

    // 4. Other sample rates: 8 kHz decimation keeps the timeline.
    {
        std::vector<float> c8;
        for (size_t i = 0; i + 1 < clip.size(); i += 2) c8.push_back(0.5f * (clip[i] + clip[i + 1]));
        const auto r8 = segments_of(take(parakeet_capi_vad_pcm_json(ctx, c8.data(), (int)c8.size(), 8000, nullptr)));
        CHECK(!r8.empty() && std::fabs(r8.front().s - a0) < 0.6 && std::fabs(r8.back().e - b1) < 0.6);
    }

    // 5. File variant equals PCM variant.
    {
        const std::string jf = take(parakeet_capi_vad_path_json(ctx, "tests/fixtures/speech.wav", nullptr));
        const std::string jq = take(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), (int)sp.samples.size(), 16000, nullptr));
        CHECK(!jf.empty() && jf == jq);
        CHECK(!segments_of(jf).empty());
    }

    // 6. Edge cases and errors.
    {
        const std::string je = take(parakeet_capi_vad_pcm_json(ctx, nullptr, 0, 16000, nullptr));
        CHECK(!je.empty() && segments_of(je).empty());
        std::vector<float> tiny(800, 0.0f);  // 50 ms
        CHECK(parakeet_capi_vad_pcm_json(ctx, tiny.data(), (int)tiny.size(), 16000, nullptr) != nullptr ||
              std::strlen(parakeet_capi_last_error(ctx)) > 0);
        const char* bad_opts[] = {"{\"threshold\":0}", "{\"threshold\":1.5}", "{\"min_pause\":-1}",
                                  "{\"mode\":\"x\"}", "{\"nope\":1}", "{\"threshold\":", "[1]",
                                  "{\"probabilities\":1}", "{} x"};
        for (const char* o : bad_opts) {
            CHECK(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), (int)sp.samples.size(), 16000, o) == nullptr);
            CHECK(std::strlen(parakeet_capi_last_error(ctx)) > 0);
        }
        CHECK(parakeet_capi_vad_pcm_json(ctx, nullptr, 5, 16000, nullptr) == nullptr);
        CHECK(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), 5, 0, nullptr) == nullptr);
        CHECK(parakeet_capi_vad_path_json(ctx, nullptr, nullptr) == nullptr);
        CHECK(parakeet_capi_vad_path_json(ctx, "/nonexistent.wav", nullptr) == nullptr);
        CHECK(parakeet_capi_vad_pcm_json(nullptr, sp.samples.data(), 5, 16000, nullptr) == nullptr);
        CHECK(!take(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), (int)sp.samples.size(), 16000, "  {}  ")).empty());
        CHECK(std::strlen(parakeet_capi_last_error(ctx)) == 0);
    }

    // 7. Threads: one context from 4 threads, and one context per thread. Same result as serial.
    {
        std::vector<std::string> out(4);
        std::vector<std::thread> th;
        for (int t = 0; t < 4; ++t)
            th.emplace_back([&, t] { out[t] = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, nullptr)); });
        for (auto& x : th) x.join();
        for (int t = 0; t < 4; ++t) CHECK(out[t] == j);
        std::vector<std::string> out2(3);
        th.clear();
        for (int t = 0; t < 3; ++t)
            th.emplace_back([&, t] {
                parakeet_ctx* c = parakeet_capi_load(ultra);
                if (c) { out2[t] = take(parakeet_capi_vad_pcm_json(c, clip.data(), (int)clip.size(), 16000, nullptr)); parakeet_capi_free(c); }
            });
        for (auto& x : th) x.join();
        for (int t = 0; t < 3; ++t) CHECK(out2[t] == j);
        // With the backend pool on, concurrent calls still agree.
        parakeet_capi_set_concurrency(ctx, 2, 2);
        th.clear();
        for (int t = 0; t < 4; ++t)
            th.emplace_back([&, t] { out[t] = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, nullptr)); });
        for (auto& x : th) x.join();
        for (int t = 0; t < 4; ++t) CHECK(out[t] == j);
        parakeet_capi_set_concurrency(ctx, 1, 0);
    }
    parakeet_capi_free(ctx);

    // 8. Packed Redux (CPU only): same document shape, same backend report.
    if (redux) {
        parakeet_ctx* rc = parakeet_capi_load(redux);
        CHECK(rc != nullptr);
        if (rc) {
            const std::string jr = take(parakeet_capi_vad_pcm_json(rc, clip.data(), (int)clip.size(), 16000, nullptr));
            std::printf("redux: %s\n", jr.c_str());
            CHECK(jr.find("\"backend\":\"cpu\"") != std::string::npos);
            const auto rr = segments_of(jr);
            CHECK(!rr.empty() && std::fabs(rr.front().s - a0) < 0.5 && std::fabs(rr.back().e - b1) < 0.5);
            parakeet_capi_free(rc);
        }
    }

    // 9. A model without the head fails cleanly.
    if (plain) {
        parakeet_ctx* pc = parakeet_capi_load(plain);
        CHECK(pc != nullptr);
        if (pc) {
            CHECK(parakeet_capi_vad_pcm_json(pc, clip.data(), (int)clip.size(), 16000, nullptr) == nullptr);
            CHECK(std::string(parakeet_capi_last_error(pc)) == "model has no VAD head");
            CHECK(parakeet_capi_vad_path_json(pc, "tests/fixtures/speech.wav", nullptr) == nullptr);
            CHECK(std::string(parakeet_capi_last_error(pc)) == "model has no VAD head");
            parakeet_capi_free(pc);
        }
    }

    if (failures) return 1;
    std::puts("test_capi_vad: OK");
    return 0;
}

// parakeet_capi_speaker_embed_pcm / parakeet_capi_free_floats.
// The argument checks need no model. The embedding checks run on each of:
//   PARAKEET_TEST_VD_GGUF       a standalone speaker-encoder GGUF (voice-detect.cpp)
//   PARAKEET_TEST_BUNDLE_VOICE  a bundle GGUF with a "voice" component (component name "voice",
//                               or PARAKEET_TEST_BUNDLE_VOICE_COMPONENT)
// With neither set the test skips (77) after the argument checks. With both set, it also checks
// that the bundle component embeds in the same space as the standalone file when it was built
// from the same encoder (PARAKEET_TEST_BUNDLE_VOICE_SAME=1; cosine >= 0.999).
#include "parakeet_capi.h"

#include "audio_io.hpp"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

static int failures = 0;
#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            std::fprintf(stderr, "FAIL: %s (line %d)\n", #cond, __LINE__);  \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

static std::vector<float> slice(const std::vector<float>& x, double a, double b) {
    return std::vector<float>(x.begin() + (long)(a * 16000), x.begin() + (long)(b * 16000));
}

static std::vector<float> embed(parakeet_ctx* c, const std::vector<float>& pcm, int sr) {
    float* e = nullptr;
    int d = 0;
    std::vector<float> v;
    if (parakeet_capi_speaker_embed_pcm(c, pcm.data(), (int)pcm.size(), sr, &e, &d) == 0 && e && d > 0)
        v.assign(e, e + d);
    parakeet_capi_free_floats(e);
    return v;
}

static double dot(const std::vector<float>& a, const std::vector<float>& b) {
    double s = 0;
    for (size_t i = 0; i < a.size() && i < b.size(); ++i) s += (double)a[i] * b[i];
    return s;
}
static double cosine(const std::vector<float>& a, const std::vector<float>& b) {
    return dot(a, b) / (std::sqrt(dot(a, a)) * std::sqrt(dot(b, b)) + 1e-12);
}

static void run(const char* label, parakeet_ctx* spk, const std::vector<float>& wav) {
    std::fprintf(stderr, "-- %s\n", label);
    CHECK(parakeet_capi_model_kind(spk) == PARAKEET_MODEL_KIND_SPEAKER);
    const int dim = parakeet_capi_speaker_dim(spk);
    CHECK(dim >= 128);

    const auto a0 = slice(wav, 0.6, 4.6), a1 = slice(wav, 14.9, 18.7), b0 = slice(wav, 6.9, 10.9);
    const auto ea0 = embed(spk, a0, 16000);
    CHECK((int)ea0.size() == dim);
    CHECK(std::fabs(std::sqrt(dot(ea0, ea0)) - 1.0) < 1e-3);  // L2-normalized

    // The out parameters on success.
    {
        float* e = nullptr;
        int d = -1;
        CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), (int)a0.size(), 16000, &e, &d) == 0);
        CHECK(e != nullptr && d == dim);
        // Determinism: the same audio twice gives the same vector.
        CHECK(e && d == dim && std::memcmp(e, ea0.data(), (size_t)dim * sizeof(float)) == 0);
        parakeet_capi_free_floats(e);
    }

    // Same voice scores higher than two different voices.
    const auto ea1 = embed(spk, a1, 16000), eb0 = embed(spk, b0, 16000);
    const double same = cosine(ea0, ea1), diff = cosine(ea0, eb0);
    std::fprintf(stderr, "   same voice %.3f, different voices %.3f\n", same, diff);
    CHECK(same > diff);
    CHECK(same > 0.5);

    // Two different synthetic signals (a tone and a noise burst) give valid, different vectors.
    // Their cosine is not compared with the voice scores: such signals are outside the
    // training distribution.
    {
        std::vector<float> tone(32000), noise(32000);
        unsigned s = 12345;
        for (size_t i = 0; i < tone.size(); ++i) {
            tone[i] = 0.3f * std::sin(2.0f * 3.14159265f * 220.0f * (float)i / 16000.0f);
            s = s * 1664525u + 1013904223u;
            noise[i] = 0.3f * ((float)(s >> 8) / 8388608.0f - 1.0f);
        }
        const auto et = embed(spk, tone, 16000), en = embed(spk, noise, 16000);
        CHECK((int)et.size() == dim && (int)en.size() == dim);
        CHECK(et != en && cosine(et, en) < 0.999);
        CHECK(embed(spk, tone, 16000) == et);
    }

    // Another sample rate is resampled: 8 kHz made by averaging pairs of samples.
    {
        std::vector<float> lo(a0.size() / 2);
        for (size_t i = 0; i < lo.size(); ++i) lo[i] = 0.5f * (a0[2 * i] + a0[2 * i + 1]);
        const auto e8 = embed(spk, lo, 8000);
        CHECK((int)e8.size() == dim);
        CHECK(cosine(e8, ea0) > 0.7);
        CHECK(!embed(spk, a0, 44100).empty());
    }

    // Errors set the outputs to NULL / 0 and the message on the ctx.
    float* e = reinterpret_cast<float*>(0x1);
    int d = 7;
    CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), (int)a0.size(), 0, &e, &d) != 0);
    CHECK(e == nullptr && d == 0);
    CHECK(std::strlen(parakeet_capi_last_error(spk)) > 0);
    e = reinterpret_cast<float*>(0x1);
    CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), (int)a0.size(), -16000, &e, &d) != 0 && e == nullptr);
    CHECK(parakeet_capi_speaker_embed_pcm(spk, nullptr, 100, 16000, &e, &d) != 0 && e == nullptr);
    CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), 0, 16000, &e, &d) != 0 && e == nullptr);
    CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), -5, 16000, &e, &d) != 0 && e == nullptr);
    CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), (int)a0.size(), 16000, nullptr, &d) != 0);
    CHECK(parakeet_capi_speaker_embed_pcm(spk, a0.data(), (int)a0.size(), 16000, &e, nullptr) != 0);
    // The ctx still works after errors.
    CHECK(embed(spk, a0, 16000) == ea0);
}

int main() {
    // Argument checks that need no model.
    {
        float* e = reinterpret_cast<float*>(0x1);
        int d = 7;
        const float pcm[160] = {0};
        CHECK(parakeet_capi_speaker_embed_pcm(nullptr, pcm, 160, 16000, &e, &d) != 0);
        CHECK(e == nullptr && d == 0);
        parakeet_capi_free_floats(nullptr);  // safe on NULL
    }

    const char* vd = std::getenv("PARAKEET_TEST_VD_GGUF");
    const char* bundle = std::getenv("PARAKEET_TEST_BUNDLE_VOICE");
    if (!vd && !bundle) {
        std::puts("skip: PARAKEET_TEST_VD_GGUF or PARAKEET_TEST_BUNDLE_VOICE must be set");
        return failures ? 1 : 77;
    }

    pk::Audio wav;
    if (!pk::load_audio_16k_mono(std::string(PK_SOURCE_DIR) + "/tests/fixtures/two_speakers.wav", wav)) return 1;

    parakeet_ctx *s1 = nullptr, *s2 = nullptr;
    if (vd) {
        s1 = parakeet_capi_load(vd);
        if (!s1) { std::fprintf(stderr, "skip: load speaker model (built without voice-detect?)\n"); return 77; }
        run("standalone speaker GGUF", s1, wav.samples);
    }
    if (bundle) {
        const char* comp = std::getenv("PARAKEET_TEST_BUNDLE_VOICE_COMPONENT");
        s2 = parakeet_capi_load_component(bundle, comp ? comp : "voice");
        if (!s2) {
            std::fprintf(stderr, "FAIL: load bundle voice component: %s\n", parakeet_capi_load_error());
            ++failures;
        } else {
            run("bundle voice component", s2, wav.samples);
            // A context of another kind is refused with a message on that ctx.
            parakeet_ctx* other = parakeet_capi_load_component(bundle, "asr");
            if (other) {
                float* e = reinterpret_cast<float*>(0x1);
                int d = 7;
                const float pcm[1600] = {0};
                CHECK(parakeet_capi_speaker_embed_pcm(other, pcm, 1600, 16000, &e, &d) != 0);
                CHECK(e == nullptr && d == 0 && std::strlen(parakeet_capi_last_error(other)) > 0);
                parakeet_capi_free(other);
            }
        }
    }
    if (s1 && s2) {
        const char* same = std::getenv("PARAKEET_TEST_BUNDLE_VOICE_SAME");
        if (same && same[0] == '1') {
            const auto a0 = slice(wav.samples, 0.6, 4.6);
            const auto x = embed(s1, a0, 16000), y = embed(s2, a0, 16000);
            const double c = cosine(x, y);
            std::fprintf(stderr, "   standalone vs bundle cosine %.6f\n", c);
            CHECK(x.size() == y.size() && c >= 0.999);
        }
    }
    parakeet_capi_free(s1);
    parakeet_capi_free(s2);
    std::fprintf(stderr, failures ? "FAILED (%d)\n" : "ok\n", failures);
    return failures ? 1 : 0;
}

// Diarize-only naming through the C-API, with a registry filled by
// add_embedding from embeddings the folded encoder computes.
//   PARAKEET_TEST_DIAR_GGUF, PARAKEET_TEST_VD_GGUF (required, else skip 77)
#include "audio_io.hpp"
#include "parakeet_capi.h"
#include "speaker_encoder.hpp"
#include "speaker_model_identity.hpp"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

static int failures = 0;
#define CHECK(cond)                                                          \
    do {                                                                     \
        if (!(cond)) {                                                       \
            std::fprintf(stderr, "FAIL: %s (line %d)\n", #cond, __LINE__);  \
            ++failures;                                                      \
        }                                                                    \
    } while (0)

static std::vector<float> slice(const std::vector<float>& x, double a, double b) {
    return std::vector<float>(x.begin() + (long)(a * 16000), x.begin() + (long)(b * 16000));
}

// Splits the "names" object of a document into its names and scores, in order.
static void parse_names(const std::string& doc, std::vector<std::string>& names, std::vector<float>& scores) {
    size_t p = doc.find("\"names\":");
    if (p == std::string::npos) return;
    const std::string key = "\"name\":\"";
    while ((p = doc.find(key, p)) != std::string::npos) {
        p += key.size();
        const size_t e = doc.find('"', p);
        names.push_back(doc.substr(p, e - p));
        const size_t sp = doc.find("\"score\":", e);
        scores.push_back(std::strtof(doc.c_str() + sp + 8, nullptr));
        p = sp;
    }
}

int main() {
    const char* diar_path = std::getenv("PARAKEET_TEST_DIAR_GGUF");
    const char* vd_path = std::getenv("PARAKEET_TEST_VD_GGUF");
    if (!diar_path || !vd_path) return 77;
    if (!pk::SpeakerEncoder::available()) return 77;

    pk::Audio wav;
    if (!pk::load_audio_16k_mono(std::string(PK_SOURCE_DIR) + "/tests/fixtures/two_speakers.wav", wav)) return 1;

    // Embeddings of the two voices, computed outside the C-API on purpose:
    // this is what LocalAI hands over (vectors, not audio).
    auto enc = pk::SpeakerEncoder::load(vd_path);
    if (!enc) { std::fprintf(stderr, "FAIL: load speaker model\n"); return 1; }
    std::vector<float> ea, eb;
    const auto ca = slice(wav.samples, 0.6, 4.6), cb = slice(wav.samples, 6.9, 10.9);
    CHECK(enc->embed(ca.data(), (int)ca.size(), ea));
    CHECK(enc->embed(cb.data(), (int)cb.size(), eb));

    parakeet_ctx* diar = parakeet_capi_load(diar_path);
    parakeet_ctx* spk = parakeet_capi_load(vd_path);
    CHECK(diar && spk);
    CHECK(parakeet_capi_speaker_identity(diar) == nullptr);
    if (spk) CHECK(pk::speaker_model_identity(vd_path) == parakeet_capi_speaker_identity(spk));
    parakeet_speaker_registry* reg = parakeet_capi_speaker_registry_new();
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "second_voice", eb.data(), (int)eb.size()) == 0);
    CHECK(parakeet_capi_speaker_registry_add_embedding(reg, "first_voice", ea.data(), (int)ea.size()) == 0);

    // Defaults: slot 0 is voice A (first to speak), slot 1 is voice B. The registry order is
    // reversed on purpose, so arrival-order naming would fail.
    std::vector<std::string> n1;
    std::vector<float> s1;
    char* j = parakeet_capi_diarize_named_pcm_json(diar, spk, reg, wav.samples.data(), (int)wav.samples.size(),
                                                    16000, 0.0f, 0.0f);
    CHECK(j != nullptr);
    if (j) {
        const std::string s = j;
        CHECK(s.find("\"segments\":[{\"speaker\":0") != std::string::npos);
        CHECK(s.find("\"names\":{\"0\":{\"name\":\"first_voice\"") != std::string::npos);
        CHECK(s.find("\"1\":{\"name\":\"second_voice\"") != std::string::npos);
        CHECK(s.find("speaker_profiles") == std::string::npos);
        CHECK(s.find("embedding") == std::string::npos);
        parse_names(s, n1, s1);
        parakeet_capi_free_string(j);
    }

    // Public opt-in succeeds without enrollment; the old named result stays unchanged.
    {
        auto* empty = parakeet_capi_speaker_registry_new();
        char* plain = parakeet_capi_diarize_named_pcm_json(diar, spk, empty,
            wav.samples.data(), (int)wav.samples.size(), 16000, 0, 0);
        char* exported = parakeet_capi_diarize_profiles_pcm_json(diar, spk, nullptr,
            wav.samples.data(), (int)wav.samples.size(), 16000, 0, 0);
        CHECK(plain && exported);
        if (plain && exported) {
            const std::string old(plain), doc(exported);
            CHECK(doc.substr(0, old.size()-1) == old.substr(0, old.size()-1));
            CHECK(doc.find("\"speaker_profiles\":{\"version\":1") != std::string::npos);
            CHECK(doc.find(parakeet_capi_speaker_identity(spk)) != std::string::npos);
            CHECK(doc.find("\"dimension\":" + std::to_string(parakeet_capi_speaker_dim(spk))) != std::string::npos);
            CHECK(doc.find("\"unavailable_reason\":null,\"embedding\":[") != std::string::npos);
            CHECK(doc.find("embedding") > doc.find("speaker_profiles"));
        }
        CHECK(parakeet_capi_speaker_registry_size(empty) == 0);
        parakeet_capi_free_string(plain);
        parakeet_capi_free_string(exported);
        parakeet_capi_speaker_registry_free(empty);
    }

    // A registry built with enroll from the same two clips gives the same names and scores.
    {
        parakeet_speaker_registry* reg2 = parakeet_capi_speaker_registry_new();
        CHECK(parakeet_capi_speaker_enroll(reg2, spk, "first_voice", ca.data(), (int)ca.size(), 16000) == 0);
        CHECK(parakeet_capi_speaker_enroll(reg2, spk, "second_voice", cb.data(), (int)cb.size(), 16000) == 0);
        std::vector<std::string> n2;
        std::vector<float> s2;
        j = parakeet_capi_diarize_named_pcm_json(diar, spk, reg2, wav.samples.data(), (int)wav.samples.size(),
                                                  16000, 0.0f, 0.0f);
        CHECK(j != nullptr);
        if (j) {
            parse_names(j, n2, s2);
            parakeet_capi_free_string(j);
        }
        CHECK(!n1.empty() && n1 == n2 && s1.size() == s2.size());
        for (size_t i = 0; i < s1.size() && i < s2.size(); ++i) CHECK(std::fabs(s1[i] - s2[i]) < 1e-3f);
        parakeet_capi_speaker_registry_free(reg2);
    }

    // The threshold reaches the identifier: above every genuine score, nothing is named.
    j = parakeet_capi_diarize_named_pcm_json(diar, spk, reg, wav.samples.data(), (int)wav.samples.size(),
                                              16000, 0.999f, 0.0f);
    CHECK(j != nullptr);
    if (j) {
        const std::string s = j;
        CHECK(s.find("\"name\":\"\"") != std::string::npos);
        CHECK(s.find("first_voice") == std::string::npos && s.find("second_voice") == std::string::npos);
        parakeet_capi_free_string(j);
    }

    // The margin reaches the identifier. Two registries whose only difference is a runner-up:
    // "a1" and "a2" hold the very same vector (best minus runner-up is exactly 0, so the default
    // 0.05 margin calls voice A unknown), while "a1" alone has no runner-up and is named.
    // The construction is independent of the encoder. (A large margin such as 0.9 on the main
    // registry is not robust: WeSpeaker scores impostors near 0, so best minus second best can
    // exceed 0.9 and the slot is still named.)
    {
        parakeet_speaker_registry* tie = parakeet_capi_speaker_registry_new();
        parakeet_speaker_registry* solo = parakeet_capi_speaker_registry_new();
        CHECK(parakeet_capi_speaker_registry_add_embedding(tie, "a1", ea.data(), (int)ea.size()) == 0);
        CHECK(parakeet_capi_speaker_registry_add_embedding(tie, "a2", ea.data(), (int)ea.size()) == 0);
        CHECK(parakeet_capi_speaker_registry_add_embedding(solo, "a1", ea.data(), (int)ea.size()) == 0);
        j = parakeet_capi_diarize_named_pcm_json(diar, spk, tie, wav.samples.data(), (int)wav.samples.size(),
                                                  16000, 0.0f, 0.0f);
        CHECK(j != nullptr);
        if (j) {
            const std::string s = j;
            CHECK(s.find("\"names\":{\"0\":{\"name\":\"\"") != std::string::npos);   // a tie is unknown
            CHECK(s.find("a1") == std::string::npos && s.find("a2") == std::string::npos);
            parakeet_capi_free_string(j);
        }
        j = parakeet_capi_diarize_named_pcm_json(diar, spk, solo, wav.samples.data(), (int)wav.samples.size(),
                                                  16000, 0.0f, 0.0f);
        CHECK(j != nullptr);
        if (j) {
            CHECK(std::string(j).find("\"names\":{\"0\":{\"name\":\"a1\"") != std::string::npos);
            parakeet_capi_free_string(j);
        }
        parakeet_capi_speaker_registry_free(tie);
        parakeet_capi_speaker_registry_free(solo);
    }
    // A negative margin is refused by the identifier's validation, on the speaker ctx.
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, reg, wav.samples.data(), (int)wav.samples.size(),
                                                16000, 0.0f, -0.1f) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(spk), "invalid speaker options") != nullptr);

    // Invalid options and a non-16k input rate.
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, reg, wav.samples.data(), (int)wav.samples.size(),
                                                16000, 2.0f, 0.0f) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(spk), "invalid speaker options") != nullptr);
    {
        std::vector<float> twice;   // the same audio at 32 kHz (each sample repeated): must still name both
        for (float v : wav.samples) { twice.push_back(v); twice.push_back(v); }
        j = parakeet_capi_diarize_named_pcm_json(diar, spk, reg, twice.data(), (int)twice.size(), 32000, 0.0f, 0.0f);
        CHECK(j != nullptr);
        if (j) {
            const std::string s = j;
            CHECK(s.find("first_voice") != std::string::npos && s.find("second_voice") != std::string::npos);
            parakeet_capi_free_string(j);
        }
    }

    // Error paths, and which ctx carries each message.
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, nullptr, reg, wav.samples.data(), 16000, 16000, 0, 0) == nullptr);
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, nullptr, wav.samples.data(), 16000, 16000, 0, 0) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(spk), "needs a registry") != nullptr);
    // A speaker ctx passed as `diar`: the message is on that ctx.
    CHECK(parakeet_capi_diarize_named_pcm_json(spk, spk, reg, wav.samples.data(), 16000, 16000, 0, 0) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(spk), "holds a speaker model; diarize_* needs a diarization model") != nullptr);
    // A diarization ctx passed as `speaker`: the message is on that ctx.
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, diar, reg, wav.samples.data(), 16000, 16000, 0, 0) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(diar), "holds a diarization model; a speaker model is needed here") != nullptr);
    // Bad samples: "invalid samples buffer" on diar.
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, reg, nullptr, 16000, 16000, 0, 0) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(diar), "invalid samples buffer") != nullptr);
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, reg, wav.samples.data(), 0, 16000, 0, 0) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(diar), "invalid samples buffer") != nullptr);
    CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, reg, wav.samples.data(), 16000, 0, 0, 0) == nullptr);
    CHECK(std::strstr(parakeet_capi_last_error(diar), "invalid sample rate") != nullptr);
    // A registry made for a different encoder size is refused with both sizes in the message, on
    // the speaker ctx, and before diarization runs (the whole fixture is passed, the diar ctx stays clean, although the call before it left a message there).
    {
        parakeet_speaker_registry* wrong = parakeet_capi_speaker_registry_new();
        const float small[3] = {1, 0, 0};
        CHECK(parakeet_capi_speaker_registry_add_embedding(wrong, "x", small, 3) == 0);
        CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, wrong, wav.samples.data(), (int)wav.samples.size(),
                                                    16000, 0, 0) == nullptr);
        const std::string msg = parakeet_capi_last_error(spk);
        const std::string want = "this model produces " + std::to_string(parakeet_capi_speaker_dim(spk));
        CHECK(msg.find("3-value") != std::string::npos);
        CHECK(msg.find(want) != std::string::npos);
        CHECK(std::strlen(parakeet_capi_last_error(diar)) == 0);
        parakeet_capi_speaker_registry_free(wrong);
    }

    // Only the ctx that the failure belongs to carries a message: a failure on one ctx must not
    // leave an older message on the other.
    {
        parakeet_speaker_registry* wrong = parakeet_capi_speaker_registry_new();
        const float small[3] = {1, 0, 0};
        CHECK(parakeet_capi_speaker_registry_add_embedding(wrong, "x", small, 3) == 0);
        // speaker fails, then diar fails: the speaker message is gone.
        CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, wrong, wav.samples.data(), 16000, 16000, 0, 0) == nullptr);
        CHECK(std::strlen(parakeet_capi_last_error(spk)) > 0);
        CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, reg, nullptr, 16000, 16000, 0, 0) == nullptr);
        CHECK(std::strstr(parakeet_capi_last_error(diar), "invalid samples buffer") != nullptr);
        CHECK(std::strlen(parakeet_capi_last_error(spk)) == 0);
        // diar fails, then speaker fails: the diar message is gone.
        CHECK(parakeet_capi_diarize_named_pcm_json(diar, spk, wrong, wav.samples.data(), 16000, 16000, 0, 0) == nullptr);
        CHECK(std::strstr(parakeet_capi_last_error(spk), "3-value") != nullptr);
        CHECK(std::strlen(parakeet_capi_last_error(diar)) == 0);
        parakeet_capi_speaker_registry_free(wrong);
    }

    parakeet_capi_speaker_registry_free(reg);
    parakeet_capi_free(diar);
    parakeet_capi_free(spk);
    if (failures) { std::fprintf(stderr, "%d failure(s)\n", failures); return 1; }
    std::printf("test_capi_diarize_named: PASS\n");
    return 0;
}

// Silero VAD through the C-API: a context loaded from a Silero GGUF, the JSON
// document for both sample rates, options, errors, threads, and the streaming
// handle (same probabilities and regions as the one-shot call, any chunking).
//
// LABEL model; run from the project root (fixtures are relative).
// Env: PARAKEET_TEST_SILERO_GGUF  Silero VAD GGUF (skip 77 if unset)
#include "parakeet_capi.h"
#include "audio_io.hpp"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <random>
#include <string>
#include <thread>
#include <vector>

static int failures = 0;
#define CHECK(c) do { if (!(c)) { std::fprintf(stderr, "FAIL: %s (line %d)\n", #c, __LINE__); ++failures; } } while (0)

struct Seg { double s, e; };

static std::string take(char* p) {
    if (!p) return std::string();
    std::string s(p);
    parakeet_capi_free_string(p);
    return s;
}

// Numbers after `"start":` / `"end":` in the "segments" array.
static std::vector<Seg> segments_of(const std::string& j) {
    std::vector<Seg> out;
    size_t pos = j.find("\"segments\":[");
    if (pos == std::string::npos) return out;
    const size_t end = j.find(']', pos);
    while (true) {
        pos = j.find("\"start\":", pos);
        if (pos == std::string::npos || pos > end) break;
        Seg g{};
        g.s = std::atof(j.c_str() + pos + 8);
        const size_t q = j.find("\"end\":", pos);
        g.e = std::atof(j.c_str() + q + 6);
        out.push_back(g);
        pos = q + 6;
    }
    return out;
}

// The values of the array that follows `key` (e.g. "probabilities":[...]).
static std::vector<double> array_of(const std::string& j, const char* key) {
    std::vector<double> out;
    size_t pos = j.find(std::string("\"") + key + "\":[");
    if (pos == std::string::npos) return out;
    pos += std::strlen(key) + 4;
    while (j[pos] != ']') {
        char* e = nullptr;
        out.push_back(std::strtod(j.c_str() + pos, &e));
        pos = (size_t)(e - j.c_str());
        if (j[pos] == ',') ++pos;
    }
    return out;
}

// "events":[{"type":"start","time":1.2},...] as (is_start, time).
static std::vector<std::pair<bool, double>> events_of(const std::string& j) {
    std::vector<std::pair<bool, double>> out;
    size_t pos = j.find("\"events\":[");
    if (pos == std::string::npos) return out;
    const size_t end = j.find(']', pos);
    while (true) {
        pos = j.find("\"type\":\"", pos);
        if (pos == std::string::npos || pos > end) break;
        const bool st = j.compare(pos + 8, 5, "start") == 0;
        const size_t q = j.find("\"time\":", pos);
        out.emplace_back(st, std::atof(j.c_str() + q + 7));
        pos = q + 7;
    }
    return out;
}

static double covered(const std::vector<Seg>& r, double a, double b) {
    double t = 0;
    for (const auto& g : r) t += std::max(0.0, std::min(g.e, b) - std::max(g.s, a));
    return t;
}

int main() {
    const char* silero = std::getenv("PARAKEET_TEST_SILERO_GGUF");
    if (!silero) { std::puts("skip: PARAKEET_TEST_SILERO_GGUF unset"); return 77; }

    pk::Audio sp;
    if (!pk::load_audio_16k_mono("tests/fixtures/speech.wav", sp)) { std::fprintf(stderr, "no fixture\n"); return 1; }
    const double sp_len = (double)sp.samples.size() / 16000.0;
    std::mt19937 rng(1);
    std::normal_distribution<float> nd(0.f, 0.0005f);
    auto silence = [&](double sec) { std::vector<float> v((size_t)(sec * 16000)); for (auto& x : v) x = nd(rng); return v; };
    std::vector<float> clip;
    auto add = [&](const std::vector<float>& v) { clip.insert(clip.end(), v.begin(), v.end()); };
    add(silence(2.0)); add(sp.samples); add(silence(2.5)); add(sp.samples); add(silence(2.0));
    const double a0 = 2.0, a1 = 2.0 + sp_len, b0 = a1 + 2.5, b1 = b0 + sp_len;
    const double total = (double)clip.size() / 16000.0;

    parakeet_ctx* ctx = parakeet_capi_load(silero);
    if (!ctx) { std::fprintf(stderr, "load failed\n"); return 1; }
    CHECK(parakeet_capi_model_kind(ctx) == PARAKEET_MODEL_KIND_VAD);
    CHECK(parakeet_capi_abi_version() == 10);

    // 1. Defaults: the document, regions on the original timeline.
    const std::string j = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, nullptr));
    std::printf("%s\n", j.c_str());
    CHECK(j.compare(0, 16, "{\"mode\":\"speech\"") == 0);
    CHECK(j.find("\"duration\":") != std::string::npos);
    CHECK(j.find("\"frame_sec\":0.032") != std::string::npos);
    CHECK(j.find("\"backend\":\"") != std::string::npos);
    CHECK(j.find("\"segments\":[") != std::string::npos);
    CHECK(j.find("\"probabilities\"") == std::string::npos);
    const std::vector<Seg> r = segments_of(j);
    CHECK(!r.empty());
    for (size_t i = 0; i < r.size(); ++i) {
        CHECK(r[i].e > r[i].s && r[i].s >= 0 && r[i].e <= total + 1e-6);
        if (i) CHECK(r[i].s >= r[i - 1].e);
    }
    const double tol = 0.3, tol_s = 0.7;  // speech.wav starts with about half a second of quiet
    CHECK(!r.empty() && std::fabs(r.front().s - a0) < tol_s && std::fabs(r.back().e - b1) < tol);
    CHECK(covered(r, a0, a1) > 0.7 * sp_len && covered(r, b0, b1) > 0.7 * sp_len);
    CHECK(covered(r, 0.0, a0 - tol) < 1e-9 && covered(r, a1 + tol, b0 - tol) < 1e-9 && covered(r, b1 + tol, total) < 1e-9);
    CHECK(r.size() >= 2);

    // 2. Probabilities: one per 32 ms chunk; padding changes only the edges.
    const std::string jp = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"probabilities\":true}"));
    const std::vector<double> p = array_of(jp, "probabilities");
    CHECK(p.size() == (size_t)std::ceil((double)clip.size() / 512.0));
    CHECK(segments_of(jp).size() == r.size());
    {
        double lo = 0, hi = 0; int nl = 0, nh = 0;
        for (size_t i = 0; i < p.size(); ++i) {
            const double t = (double)i * 0.032;
            if (t > 0.2 && t < a0 - 0.3) { lo += p[i]; ++nl; }
            if (t > a0 + 0.5 && t < a1 - 0.5) { hi += p[i]; ++nh; }
        }
        CHECK(nl > 0 && nh > 0 && lo / nl < 0.2 && hi / nh > 0.5);
    }
    const auto np = segments_of(take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"speech_pad\":0}")));
    CHECK(np.size() == r.size());
    for (size_t i = 0; i < np.size() && i < r.size(); ++i)
        CHECK(std::fabs((np[i].s - r[i].s) - 0.03) < 0.0015 && std::fabs((r[i].e - np[i].e) - 0.03) < 0.0015);
    // A huge min_pause merges everything between the first and last speech.
    CHECK(segments_of(take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"min_pause\":4}"))).size() == 1);
    // A threshold of 0.999 never gives more speech than the default.
    CHECK(covered(segments_of(take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"threshold\":0.999}"))), 0, total)
          <= covered(r, 0, total) + 1e-9);

    // 3. "segments" mode: cuts of at most max_segment, whole short audio kept.
    {
        std::vector<float> longclip;
        for (int i = 0; i < 4; ++i) longclip.insert(longclip.end(), clip.begin(), clip.end());
        const std::string js = take(parakeet_capi_vad_pcm_json(ctx, longclip.data(), (int)longclip.size(), 16000,
                                                              "{\"mode\":\"segments\",\"max_segment\":15}"));
        CHECK(js.find("\"mode\":\"segments\"") != std::string::npos);
        const auto sg = segments_of(js);
        CHECK(sg.size() >= 4);
        for (const auto& g : sg) CHECK(g.e - g.s <= 15.0 + 1e-6);
        CHECK(covered(sg, 0, (double)longclip.size() / 16000.0) > 0.85 * 8 * sp_len);
        const auto w = segments_of(take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, "{\"mode\":\"segments\"}")));
        CHECK(w.size() == 1 && w[0].s == 0.0 && std::fabs(w[0].e - total) < 0.002);
    }

    // 4. 8 kHz is taken as it is (frame_sec stays 0.032); other rates are resampled.
    {
        std::vector<float> c8;
        for (size_t i = 0; i + 1 < clip.size(); i += 2) c8.push_back(0.5f * (clip[i] + clip[i + 1]));
        const std::string j8 = take(parakeet_capi_vad_pcm_json(ctx, c8.data(), (int)c8.size(), 8000, "{\"probabilities\":true}"));
        CHECK(j8.find("\"frame_sec\":0.032") != std::string::npos);
        CHECK(array_of(j8, "probabilities").size() == (size_t)std::ceil((double)c8.size() / 256.0));
        const auto r8 = segments_of(j8);
        CHECK(r8.size() >= 2 && std::fabs(r8.front().s - a0) < tol_s && std::fabs(r8.back().e - b1) < tol);
        // 22.05 kHz: resampled to 16 kHz first, the timeline is kept.
        std::vector<float> c22 = pk::resample_linear(clip, 16000, 22050);
        const auto r22 = segments_of(take(parakeet_capi_vad_pcm_json(ctx, c22.data(), (int)c22.size(), 22050, nullptr)));
        CHECK(r22.size() >= 2 && std::fabs(r22.front().s - a0) < tol_s && std::fabs(r22.back().e - b1) < tol);
    }

    // 5. File variant equals PCM variant.
    {
        const std::string jf = take(parakeet_capi_vad_path_json(ctx, "tests/fixtures/speech.wav", nullptr));
        const std::string jq = take(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), (int)sp.samples.size(), 16000, nullptr));
        CHECK(!jf.empty() && jf == jq && !segments_of(jf).empty());
    }

    // 6. Edge cases and errors.
    {
        const std::string je = take(parakeet_capi_vad_pcm_json(ctx, nullptr, 0, 16000, nullptr));
        CHECK(!je.empty() && segments_of(je).empty());
        std::vector<float> tiny(100, 0.0f);   // less than one chunk
        const std::string jt = take(parakeet_capi_vad_pcm_json(ctx, tiny.data(), (int)tiny.size(), 16000, "{\"probabilities\":true}"));
        CHECK(!jt.empty() && array_of(jt, "probabilities").size() == 1 && segments_of(jt).empty());
        const char* bad_opts[] = {"{\"threshold\":0}", "{\"speech_pad\":-1}", "{\"mode\":\"x\"}", "{\"nope\":1}", "[1]", "{} x"};
        for (const char* o : bad_opts) {
            CHECK(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), (int)sp.samples.size(), 16000, o) == nullptr);
            CHECK(std::strlen(parakeet_capi_last_error(ctx)) > 0);
        }
        CHECK(parakeet_capi_vad_pcm_json(ctx, nullptr, 5, 16000, nullptr) == nullptr);
        CHECK(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), 5, 0, nullptr) == nullptr);
        CHECK(parakeet_capi_vad_path_json(ctx, nullptr, nullptr) == nullptr);
        CHECK(parakeet_capi_vad_path_json(ctx, "/nonexistent.wav", nullptr) == nullptr);
        CHECK(!take(parakeet_capi_vad_pcm_json(ctx, sp.samples.data(), (int)sp.samples.size(), 16000, "  {}  ")).empty());
        CHECK(std::strlen(parakeet_capi_last_error(ctx)) == 0);
        // Not an ASR context: the ASR entry points say so.
        CHECK(parakeet_capi_transcribe_path(ctx, "tests/fixtures/speech.wav", 0) == nullptr);
        CHECK(std::strlen(parakeet_capi_last_error(ctx)) > 0);
        // A Silero context is not an ASR context for the segmented transcription either.
        CHECK(parakeet_capi_transcribe_path_json_vad_with(ctx, ctx, "tests/fixtures/speech.wav", 0, nullptr) == nullptr);
    }

    // 7. Several threads on one context, same document as serial.
    {
        std::vector<std::string> out(4);
        std::vector<std::thread> th;
        for (int t = 0; t < 4; ++t)
            th.emplace_back([&, t] { out[t] = take(parakeet_capi_vad_pcm_json(ctx, clip.data(), (int)clip.size(), 16000, nullptr)); });
        for (auto& x : th) x.join();
        for (int t = 0; t < 4; ++t) CHECK(out[t] == j);
        std::vector<std::string> out2(3);
        th.clear();
        for (int t = 0; t < 3; ++t)
            th.emplace_back([&, t] {
                parakeet_ctx* c = parakeet_capi_load(silero);
                if (c) { out2[t] = take(parakeet_capi_vad_pcm_json(c, clip.data(), (int)clip.size(), 16000, nullptr)); parakeet_capi_free(c); }
            });
        for (auto& x : th) x.join();
        for (int t = 0; t < 3; ++t) CHECK(out2[t] == j);
    }

    // 8. Streaming.
    {
        const char* opts = "{\"probabilities\":true}";
        parakeet_vad_stream* s = parakeet_capi_vad_stream_begin(ctx, 16000, opts);
        CHECK(s != nullptr);
        CHECK(parakeet_capi_vad_stream_begin(ctx, 44100, nullptr) == nullptr);
        CHECK(std::strlen(parakeet_capi_last_error(ctx)) > 0);
        CHECK(parakeet_capi_vad_stream_begin(ctx, 16000, "{\"mode\":\"segments\"}") == nullptr);
        CHECK(parakeet_capi_vad_stream_begin(ctx, 16000, "{\"bogus\":1}") == nullptr);
        // run_gate is offline only: a stream refuses it, and run_gate 0 is fine.
        CHECK(parakeet_capi_vad_stream_begin(ctx, 16000, "{\"run_gate\":0.9}") == nullptr);
        CHECK(std::string(parakeet_capi_last_error(ctx)).find("run_gate") != std::string::npos);
        {
            parakeet_vad_stream* z = parakeet_capi_vad_stream_begin(ctx, 16000, "{\"run_gate\":0}");
            CHECK(z != nullptr);
            parakeet_capi_vad_stream_free(z);
        }

        auto run = [&](parakeet_vad_stream* st, unsigned seed, std::vector<double>* probs,
                       std::vector<std::pair<bool, double>>* ev) {
            std::mt19937 g(seed);
            size_t pos = 0;
            long long next_frame = 0;
            while (pos < clip.size()) {
                size_t n = std::min<size_t>(clip.size() - pos, g() % 4 == 0 ? 0 : 1 + g() % 5000);
                const bool last = pos + n >= clip.size();
                const std::string d = take(parakeet_capi_vad_stream_feed_json(st, clip.data() + pos, (int)n, last ? 1 : 0));
                CHECK(!d.empty());
                CHECK(d.find("\"first_frame\":" + std::to_string(next_frame) + ",") != std::string::npos);
                const auto pp = array_of(d, "probabilities");
                probs->insert(probs->end(), pp.begin(), pp.end());
                next_frame += (long long)pp.size();
                const auto e = events_of(d);
                ev->insert(ev->end(), e.begin(), e.end());
                pos += n;
            }
        };
        std::vector<double> sp1, sp2;
        std::vector<std::pair<bool, double>> ev1, ev2;
        run(s, 11, &sp1, &ev1);
        // Same probabilities as the one-shot call (4 printed decimals), whatever the chunking.
        CHECK(sp1.size() == p.size());
        bool same = sp1.size() == p.size();
        for (size_t i = 0; same && i < p.size(); ++i) same = std::fabs(sp1[i] - p[i]) < 1e-9;
        CHECK(same);
        // Events equal the regions of the one-shot "speech" mode (to the printed 3 decimals).
        CHECK(ev1.size() == 2 * r.size());
        for (size_t i = 0; i < r.size() && 2 * i + 1 < ev1.size(); ++i) {
            CHECK(ev1[2 * i].first && !ev1[2 * i + 1].first);
            CHECK(std::fabs(ev1[2 * i].second - r[i].s) < 1.5e-3 && std::fabs(ev1[2 * i + 1].second - r[i].e) < 1.5e-3);
        }
        // Finished: a further feed fails until reset(); then the same run repeats.
        CHECK(parakeet_capi_vad_stream_feed_json(s, clip.data(), 10, 0) == nullptr);
        CHECK(parakeet_capi_vad_stream_reset(s) == 0);
        run(s, 99, &sp2, &ev2);
        CHECK(sp2 == sp1 && ev2 == ev1);
        parakeet_capi_vad_stream_free(s);
        // Bad arguments.
        s = parakeet_capi_vad_stream_begin(ctx, 16000, nullptr);
        CHECK(s != nullptr);
        CHECK(parakeet_capi_vad_stream_feed_json(s, nullptr, 5, 0) == nullptr);
        CHECK(parakeet_capi_vad_stream_feed_json(s, clip.data(), -1, 0) == nullptr);
        const std::string d0 = take(parakeet_capi_vad_stream_feed_json(s, nullptr, 0, 1));   // empty stream
        CHECK(!d0.empty() && events_of(d0).empty() && d0.find("\"probabilities\"") == std::string::npos);
        parakeet_capi_vad_stream_free(s);
        // An 8 kHz stream, and two streams on two threads sharing the context.
        std::vector<float> c8;
        for (size_t i = 0; i + 1 < clip.size(); i += 2) c8.push_back(0.5f * (clip[i] + clip[i + 1]));
        std::vector<std::vector<std::pair<bool, double>>> evs(3);
        std::vector<std::thread> th;
        for (int t = 0; t < 3; ++t)
            th.emplace_back([&, t] {
                const bool r8 = t == 2;
                parakeet_vad_stream* st = parakeet_capi_vad_stream_begin(ctx, r8 ? 8000 : 16000, nullptr);
                if (!st) return;
                const std::vector<float>& src = r8 ? c8 : clip;
                for (size_t pos = 0; pos < src.size(); pos += 1777) {
                    const size_t n = std::min<size_t>(1777, src.size() - pos);
                    const std::string d = take(parakeet_capi_vad_stream_feed_json(st, src.data() + pos, (int)n, pos + n >= src.size()));
                    const auto e = events_of(d);
                    evs[t].insert(evs[t].end(), e.begin(), e.end());
                }
                parakeet_capi_vad_stream_free(st);
            });
        for (auto& x : th) x.join();
        CHECK(evs[0].size() == 2 * r.size() && evs[0] == evs[1]);
        CHECK(evs[2].size() >= 4 && evs[2].size() % 2 == 0 && std::fabs(evs[2].front().second - a0) < tol_s && std::fabs(evs[2].back().second - b1) < tol);
    }
    parakeet_capi_free(ctx);

    if (failures) return 1;
    std::puts("test_capi_vad_silero: OK");
    return 0;
}

// The VAD run gate on real detectors. The clip is two_speakers.wav, 1 s of
// digital silence, 12 s of seeded noise, 1 s of silence and speech.wav, so it
// has a noise stretch between two stretches of speech and is longer than the
// 30 s segment cap. Checked per detector (white and pink noise):
//   * "run_gate":0 and no option give the same JSON, byte for byte, in both
//     modes;
//   * in "speech" mode a gate never adds speech;
//   * with the Redux head at 0.92 most of the seconds the head called speech
//     inside the noise stretch are gone, and the speech stretches are unchanged;
//   * with a full ASR head the transcribe path honours the key: no word in the
//     noise stretch, and "run_gate":0 gives the document of no option.
// Env (each optional; skip 77 when none is set):
//   PARAKEET_TEST_VAD_ONLY_REDUX_GGUF  a Redux VAD-only slice (scripts/slice_vad_gguf.py)
//   PARAKEET_TEST_GGUF_REDUX_KEEP / _REDUX_DEQ / _ULTRA  ASR models with a head
//   PARAKEET_TEST_SILERO_GGUF    a Silero VAD model
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <memory>
#include <random>
#include <string>
#include <utility>
#include <vector>

#include "audio_io.hpp"
#include "model.hpp"
#include "parakeet_capi.h"

using namespace pk;

static int failures = 0;
#define CHECK(c) do { if (!(c)) { std::fprintf(stderr, "FAIL: %s (line %d)\n", #c, __LINE__); ++failures; } } while (0)

struct Seg { double a, b; };

static std::string take(char* p) {
    if (!p) return std::string();
    std::string s(p);
    parakeet_capi_free_string(p);
    return s;
}

// The "segments" array of a VAD JSON document.
static std::vector<Seg> segs_of(const std::string& j) {
    std::vector<Seg> out;
    size_t i = j.find("\"segments\":[");
    if (i == std::string::npos) return out;
    const size_t end = j.find(']', i);
    for (size_t k = j.find("\"start\":", i); k != std::string::npos && k < end; k = j.find("\"start\":", k + 1)) {
        const double a = std::atof(j.c_str() + k + 8);
        const size_t e = j.find("\"end\":", k);
        out.push_back({a, std::atof(j.c_str() + e + 6)});
    }
    return out;
}

static double overlap(const std::vector<Seg>& s, double lo, double hi) {
    double t = 0.0;
    for (const Seg& g : s) t += std::max(0.0, std::min(g.b, hi) - std::max(g.a, lo));
    return t;
}

static double covered(const std::vector<Seg>& s) { return overlap(s, -1e9, 1e9); }

static bool same(const std::vector<Seg>& a, const std::vector<Seg>& b) {
    if (a.size() != b.size()) return false;
    for (size_t i = 0; i < a.size(); ++i)
        if (std::fabs(a[i].a - b[i].a) > 1e-9 || std::fabs(a[i].b - b[i].b) > 1e-9) return false;
    return true;
}

static std::vector<Seg> within(const std::vector<Seg>& s, double lo, double hi) {
    std::vector<Seg> o;
    for (const Seg& g : s) if (g.a >= lo && g.b <= hi) o.push_back(g);
    return o;
}

// White noise, or pink noise from Paul Kellet's filter, scaled to the given RMS.
static std::vector<float> make_noise(bool pink, size_t n, float rms, unsigned seed) {
    std::mt19937 rng(seed);
    std::normal_distribution<float> nd(0.0f, 1.0f);
    std::vector<float> x(n);
    float b0 = 0, b1 = 0, b2 = 0;
    for (size_t i = 0; i < n; ++i) {
        const float w = nd(rng);
        if (pink) {
            b0 = 0.99765f * b0 + w * 0.0990460f;
            b1 = 0.96300f * b1 + w * 0.2965164f;
            b2 = 0.57000f * b2 + w * 1.0526913f;
            x[i] = b0 + b1 + b2 + w * 0.1848f;
        } else {
            x[i] = w;
        }
    }
    double e = 0.0;
    for (float v : x) e += (double)v * v;
    const float g = rms / (float)std::sqrt(e / (double)n + 1e-30);
    for (float& v : x) v *= g;
    return x;
}

static bool write_wav16(const std::string& path, const std::vector<float>& pcm) {
    std::FILE* f = std::fopen(path.c_str(), "wb");
    if (!f) return false;
    const uint32_t n = (uint32_t)pcm.size() * 2, sr = 16000, br = sr * 2, fmt = 16, riff = 36 + n;
    const uint16_t pcm_tag = 1, ch = 1, align = 2, bits = 16;
    std::fwrite("RIFF", 1, 4, f); std::fwrite(&riff, 4, 1, f); std::fwrite("WAVEfmt ", 1, 8, f);
    std::fwrite(&fmt, 4, 1, f); std::fwrite(&pcm_tag, 2, 1, f); std::fwrite(&ch, 2, 1, f);
    std::fwrite(&sr, 4, 1, f); std::fwrite(&br, 4, 1, f); std::fwrite(&align, 2, 1, f); std::fwrite(&bits, 2, 1, f);
    std::fwrite("data", 1, 4, f); std::fwrite(&n, 4, 1, f);
    for (float v : pcm) {
        const int16_t s = (int16_t)std::lrintf(std::max(-1.0f, std::min(1.0f, v)) * 32767.0f);
        std::fwrite(&s, 2, 1, f);
    }
    std::fclose(f);
    return true;
}

struct Clip {
    std::vector<float> pcm;
    double speech_a_end = 0, noise_lo = 0, noise_hi = 0, speech_b_start = 0, total = 0;
};

static Clip make_clip(bool pink) {
    Audio a, b;
    CHECK(load_audio_16k_mono("tests/fixtures/two_speakers.wav", a));
    CHECK(load_audio_16k_mono("tests/fixtures/speech.wav", b));
    Clip c;
    c.pcm = a.samples;
    c.speech_a_end = (double)c.pcm.size() / 16000.0;
    c.pcm.insert(c.pcm.end(), 16000, 0.0f);
    const std::vector<float> z = make_noise(pink, 12 * 16000, 0.08f, pink ? 11u : 7u);
    c.noise_lo = (double)c.pcm.size() / 16000.0;
    c.pcm.insert(c.pcm.end(), z.begin(), z.end());
    c.noise_hi = (double)c.pcm.size() / 16000.0;
    c.pcm.insert(c.pcm.end(), 16000, 0.0f);
    c.speech_b_start = (double)c.pcm.size() / 16000.0;
    c.pcm.insert(c.pcm.end(), b.samples.begin(), b.samples.end());
    c.total = (double)c.pcm.size() / 16000.0;
    return c;
}

static std::string vad(parakeet_ctx* ctx, const Clip& c, const char* opts) {
    return take(parakeet_capi_vad_pcm_json(ctx, c.pcm.data(), (int)c.pcm.size(), 16000, opts));
}

// `redux`: the head is the Redux head, so the gate must remove the noise.
static void check_detector(const char* path, const char* what, bool redux, double gate) {
    parakeet_ctx* ctx = parakeet_capi_load(path);
    CHECK(ctx != nullptr);
    if (!ctx) return;
    for (int pink = 0; pink < 2; ++pink) {
        const Clip c = make_clip(pink != 0);
        std::fprintf(stderr, "%s, %s noise\n", what, pink ? "pink" : "white");
        char g[64], gj[128];
        std::snprintf(g, sizeof(g), "%.2f", gate);
        for (const char* mode : {"speech", "segments"}) {
            char o0[96], o1[96], o2[128];
            std::snprintf(o0, sizeof(o0), "{\"mode\":\"%s\"}", mode);
            std::snprintf(o1, sizeof(o1), "{\"mode\":\"%s\",\"run_gate\":0}", mode);
            std::snprintf(gj, sizeof(gj), "{\"mode\":\"%s\",\"run_gate\":%s}", mode, g);
            std::snprintf(o2, sizeof(o2), "{\"mode\":\"%s\",\"run_gate\":%s,\"probabilities\":true}", mode, g);
            const std::string off = vad(ctx, c, o0);
            CHECK(!off.empty());
            CHECK(vad(ctx, c, o1) == off);                          // 0 is byte-identical to no key
            if (std::strcmp(mode, "speech") == 0) CHECK(vad(ctx, c, nullptr) == off);
            const std::string on = vad(ctx, c, gj);
            CHECK(!on.empty());
            const auto s_off = segs_of(off), s_on = segs_of(on);
            const double n_off = overlap(s_off, c.noise_lo + 0.5, c.noise_hi - 0.5);
            const double n_on = overlap(s_on, c.noise_lo + 0.5, c.noise_hi - 0.5);
            std::fprintf(stderr, "  %-8s noise stretch called speech: %.2f s off, %.2f s gate %s; total %.2f -> %.2f s\n",
                         mode, n_off, n_on, g, covered(s_off), covered(s_on));
            // The probabilities in the document are the detector's own, gate or not.
            const std::string withp = vad(ctx, c, o2);
            CHECK(!withp.empty() && withp.find("\"probabilities\"") != std::string::npos);
            if (std::strcmp(mode, "speech") == 0) {
                CHECK(covered(s_on) <= covered(s_off) + 1e-6);      // a gate never adds speech
                CHECK(n_on <= n_off + 1e-6);
                if (redux) {
                    CHECK(n_off > 2.0);                             // the noise does fool the head
                    CHECK(n_on <= 0.25 * n_off);                    // and the gate removes most of it
                    // The speech stretches keep their regions.
                    CHECK(same(within(s_off, 0.0, c.speech_a_end + 0.1), within(s_on, 0.0, c.speech_a_end + 0.1)));
                    CHECK(same(within(s_off, c.speech_b_start - 0.1, c.total), within(s_on, c.speech_b_start - 0.1, c.total)));
                    CHECK(!within(s_on, 0.0, c.speech_a_end + 0.1).empty());
                }
            } else {
                // The cuts follow the segmenter rules (last pause inside the 30 s
                // window), so a long pause can stay inside a piece; the speech
                // itself must be inside the pieces, with the gate on.
                CHECK(!s_on.empty());
                CHECK(overlap(s_on, 0.6, c.speech_a_end - 0.2) > 0.9 * (c.speech_a_end - 0.8));
                CHECK(overlap(s_on, c.speech_b_start + 0.6, c.total - 0.4) > 0.9 * (c.total - c.speech_b_start - 1.0));
            }
        }
        // Bad value through the C-API.
        CHECK(parakeet_capi_vad_pcm_json(ctx, c.pcm.data(), (int)c.pcm.size(), 16000, "{\"run_gate\":1}") == nullptr);
        CHECK(std::string(parakeet_capi_last_error(ctx)).find("run_gate") != std::string::npos);
    }
    parakeet_capi_free(ctx);
}

// A full ASR model with a head: the transcribe paths take the gate.
static void check_transcribe(const char* path, const char* what, double gate) {
    std::fprintf(stderr, "%s: transcribe\n", what);
    std::unique_ptr<Model> m = Model::load(path);
    CHECK(m != nullptr);
    if (!m || !m->config().vad.present) return;
    const Clip c = make_clip(false);
    SegmenterOpts o;
    const Transcription base = m->transcribe_pcm_vad_with_timestamps(c.pcm, 16000, Decoder::kDefault, "", o);
    SegmenterOpts z = o;
    z.run_gate = 0.0f;
    const Transcription zero = m->transcribe_pcm_vad_with_timestamps(c.pcm, 16000, Decoder::kDefault, "", z);
    CHECK(zero.text == base.text && zero.words.size() == base.words.size());
    SegmenterOpts go = o;
    go.run_gate = (float)gate;
    const Transcription on = m->transcribe_pcm_vad_with_timestamps(c.pcm, 16000, Decoder::kDefault, "", go);
    CHECK(!on.words.empty());
    size_t in_noise_on = 0, in_noise_off = 0;
    for (const Word& w : on.words) in_noise_on += (w.start > c.noise_lo + 0.5 && w.start < c.noise_hi - 0.5);
    for (const Word& w : base.words) in_noise_off += (w.start > c.noise_lo + 0.5 && w.start < c.noise_hi - 0.5);
    std::fprintf(stderr, "  words inside the noise stretch: %zu off, %zu gate %.2f; %zu / %zu words in all\n",
                 in_noise_off, in_noise_on, gate, base.words.size(), on.words.size());
    CHECK(in_noise_on == 0);
    CHECK(on.words.size() <= base.words.size());
    CHECK(m->transcribe_pcm_vad(c.pcm, 16000, Decoder::kDefault, "", go) == on.text);

    // C-API: the key reaches the segmenter; 0 and no option give the same document.
    const std::string wav = "test_vad_run_gate_model.tmp.wav";
    CHECK(write_wav16(wav, c.pcm));
    parakeet_ctx* ctx = parakeet_capi_load(path);
    CHECK(ctx != nullptr);
    if (ctx) {
        const std::string a = take(parakeet_capi_transcribe_path_json_vad_with(ctx, nullptr, wav.c_str(), 0, nullptr));
        const std::string b = take(parakeet_capi_transcribe_path_json_vad_with(ctx, nullptr, wav.c_str(), 0, "{\"run_gate\":0}"));
        const std::string d = take(parakeet_capi_transcribe_path_json_vad(ctx, wav.c_str(), 0));
        CHECK(!a.empty() && a == b && a == d);
        char opts[64];
        std::snprintf(opts, sizeof(opts), "{\"run_gate\":%.2f}", gate);
        const std::string e = take(parakeet_capi_transcribe_path_json_vad_with(ctx, nullptr, wav.c_str(), 0, opts));
        CHECK(!e.empty());
        CHECK(parakeet_capi_transcribe_path_json_vad_with(ctx, nullptr, wav.c_str(), 0, "{\"run_gate\":1.5}") == nullptr);
        CHECK(std::string(parakeet_capi_last_error(ctx)).find("run_gate") != std::string::npos);
        // Plain transcribe options have no segmenter: the key is unknown there.
        CHECK(parakeet_capi_transcribe_path_json_with(ctx, wav.c_str(), 0, "{\"run_gate\":0.9}") == nullptr);
        parakeet_capi_free(ctx);
    }
    std::remove(wav.c_str());
}

int main() {
    const char* slice = std::getenv("PARAKEET_TEST_VAD_ONLY_REDUX_GGUF");
    const char* keep = std::getenv("PARAKEET_TEST_GGUF_REDUX_KEEP");
    const char* deq = std::getenv("PARAKEET_TEST_GGUF_REDUX_DEQ");
    const char* ultra = std::getenv("PARAKEET_TEST_GGUF_ULTRA");
    const char* silero = std::getenv("PARAKEET_TEST_SILERO_GGUF");
    if (!slice && !keep && !deq && !ultra && !silero) { std::puts("skip: no model env set"); return 77; }
    if (slice) check_detector(slice, "Redux VAD slice", true, 0.92);
    if (keep) { check_detector(keep, "Redux packed", true, 0.92); check_transcribe(keep, "Redux packed", 0.92); }
    if (deq) check_detector(deq, "Redux dequantized", true, 0.92);
    if (ultra) check_detector(ultra, "Ultra", false, 0.92);
    if (silero) check_detector(silero, "Silero", false, 0.92);
    if (failures) return 1;
    std::puts("test_vad_run_gate_model: OK");
    return 0;
}

#include "tokenizer.hpp"
#include <cstdio>
#include <string>
#include <vector>

// Regression for issue #40: offline decode emits raw special tokens (e.g. the
// language tag <en-US>) in the transcript text.
//
// Root cause: src/model.cpp's four offline decode paths (decode_enc_out(),
// transcribe_16k_batch(), decode_enc_out_with_timestamps(),
// transcribe_16k_batch_with_timestamps()) all pass the raw decoded id sequence
// straight to pk::detokenize(), with no filtering. When the decoder emits a
// special-token id (a language tag for prompt-conditioned models, <EOU>, etc.),
// it lands verbatim in the output text.
//
// This test reproduces that defect using pk::detokenize() itself -- the exact,
// unmodified function every one of those four call sites invokes -- fed a
// decoded id sequence shaped like the one in the bug report (content tokens
// followed by a trailing language-tag id). It then verifies the fix: wrapping
// the same call with pk::strip_special_tokens(), exactly as model.cpp now
// does at each of the four sites, removes the tag.
int main() {
    const std::vector<std::string> pieces = {
        "\xe2\x96\x81The",  // ▁The
        "\xe2\x96\x81sun",  // ▁sun
        "<en-US>",          // language-tag special token, as in the bug report
        "<EOU>",
        "[CLS]",
    };

    // Decoded id sequence a TDT/RNNT greedy decode would produce for a
    // prompt-conditioned model: real words, then the trailing language tag.
    const std::vector<int32_t> decoded_ids = { 0, 1, 2 };

    // 1. Reproduce the reported defect: this is *exactly* what every one of
    //    the four offline decode call sites did before the fix -- hand the raw
    //    decoded ids straight to detokenize(), unmodified, no filtering.
    std::string buggy = pk::detokenize(pieces, decoded_ids);
    if (buggy.find("<en-US>") == std::string::npos) {
        std::fprintf(stderr,
                     "test_special_token_filter: test setup does not reproduce the bug; "
                     "raw detokenize() unexpectedly omitted the tag (got=[%s])\n",
                     buggy.c_str());
        return 1;
    }

    // 2. Verify the fix: model.cpp's call sites now filter with
    //    strip_special_tokens() before detokenizing. Same ids, same pieces.
    std::string fixed = pk::detokenize(pieces, pk::strip_special_tokens(pieces, decoded_ids));
    const std::string expected = "The sun";
    if (fixed != expected) {
        std::fprintf(stderr,
                     "test_special_token_filter: MISMATCH got=[%s] expected=[%s]\n",
                     fixed.c_str(), expected.c_str());
        return 1;
    }

    // Ordinary content tokens (▁-prefixed subwords) must survive untouched --
    // the filter must not over-strip real transcript text.
    std::vector<int32_t> only_words = pk::strip_special_tokens(pieces, { 0, 1 });
    if (only_words.size() != 2) {
        std::fprintf(stderr,
                     "test_special_token_filter: normal tokens were incorrectly stripped (got %zu)\n",
                     only_words.size());
        return 1;
    }

    // <...> and [...] tokens are stripped wherever they appear in the sequence,
    // not just at the end.
    std::vector<int32_t> stripped = pk::strip_special_tokens(pieces, { 0, 3, 1, 4, 2 });
    if (stripped.size() != 2) {
        std::fprintf(stderr,
                     "test_special_token_filter: bracketed special tokens not stripped (got %zu)\n",
                     stripped.size());
        return 1;
    }

    std::fprintf(stderr, "test_special_token_filter: OK\n");
    return 0;
}
